import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Board, Change, Item, Proposal, Status, View } from '../types'
import {
  KINDS, PRIORITIES, STATUSES, VIEWS, bar, createItems, deleteItem, detail, emptyBoard,
  MOVES, acceptanceProgress, actionsFor, closeBlockOf, addDraft, claimCommit, gateDone, issueBody, issueHash, issueTitle, planGithub, toMarkdown, parseTodos, todoItems, TODO_PATTERN, openQuestions, withPlanningNotes, applyGit, ago, codeOf, planBranch, reviseDraft, allowedFor, changeDraft, closeDraft, findDraft, openDrafts, keptItems, planDepths, proposalScope, linkCommit, closable, readyToClose, childRows, membersOf, dependents, moveItem, siblings, contentPrint, digest, filterItems, fingerprint, stamp, matchesQuery, migrate, groupByStatus, isClosed, STATUS_LABEL, STATUS_GLYPH, serialize, line, nextUp, progress, resolveId, sortItems, summary, updateItem, viewItems,
} from './board'
import type { DraftOps, Filter, GitCommit, ItemInput, ItemPatch, Move } from './board'

type $ = EngineInterface

const PLUGIN = 'backlog'
const PANE = 'backlog-board'
const PLAN = 'backlog-plan'
const boardAtom = atom({ plugin: 'backlog', key: 'board' } as const, null)
const viewAtom = atom({ plugin: 'backlog', key: 'view' } as const, 'active')
const selectedAtom = atom({ plugin: 'backlog', key: 'selected' } as const, null)
const editingAtom = atom({ plugin: 'backlog', key: 'editing' } as const, false)
const lastChangeAtom = atom({ plugin: 'backlog', key: 'lastChange' } as const, null)
const confirmAtom = atom({ plugin: 'backlog', key: 'confirmDelete' } as const, null)
const queryAtom = atom({ plugin: 'backlog', key: 'query' } as const, '')
const expandedAtom = atom({ plugin: 'backlog', key: 'expanded' } as const, null)
const seenAtom = atom({ plugin: 'backlog', key: 'seenAt' } as const, '')
const bandHiddenAtom = atom({ plugin: 'backlog', key: 'bandHidden' } as const, false)
const proposalAtom = atom({ plugin: 'backlog', key: 'proposal' } as const, null)
const activeDraftAtom = atom({ plugin: 'backlog', key: 'activeDraft' } as const, null)
const planConfirmAtom = atom({ plugin: 'backlog', key: 'planConfirm' } as const, null)
const planEditAtom = atom({ plugin: 'backlog', key: 'planEdit' } as const, null)
const focusedAtom = atom({ plugin: 'backlog', key: 'focused' } as const, null)
const pathAtom = atom({ plugin: 'backlog', key: 'path' } as const, '')



const GUIDE = `# Backlog (project tracker)
The mcp__backlog__* tools track this project's planned work, stored outside the repo (never write task files into it). Items: milestone > epic > story/task/bug, ids like E-2, S-3 (the number alone works). Statuses: later, todo, in_progress, review, blocked, done, cancelled.
- Use the board for work the user plans or tracks there: items they name, "the next task", "the backlog", or a plan they ask for. Don't create items as a checklist for a task you'll finish in this request.
- Planning: propose (mcp__backlog__propose, then revise) so the user reviews it; create directly only what they asked for outright. Each story: who it serves and why, the approach, 3–6 testable acceptance criteria, an estimate. No filler or ceremony items.
- Working a tracked item: set in_progress when you start. When finished, one update per item carries the ticks (\`met\`), a short comment and status review. Done is the user's call. Commit messages start with the id (\`S-12: …\`).`

const ideaPrompt = (idea: string) => `Turn this idea into planned work in the Backlog tracker (the mcp__backlog__* tools). Do not start implementing.

1. Call mcp__backlog__summary to see existing milestones and epics, and attach to them where it fits.
2. If the idea is large, create an epic with stories (each with a description, acceptance criteria and story points) and tasks under stories where they help; if it is small, create a single story, task or bug. Suggest a milestone only if the idea is a release-sized goal. Put everything in one mcp__backlog__propose call, linking new items with \`ref\`: the user reviews the plan in a dialog and keeps what they want. Don't call create.
3. Reply with the plan as a short tree in one or two lines per item, and say it is waiting for their review in the dialog.

Idea: ${idea}`

const branchHint = (i: Item) => (i.code?.branches?.length ? ` Work on its branch ${i.code.branches[0]} (git switch ${i.code.branches[0]} if you're not on it).` : '')

const planPrompt = (topic: string, id: string) => `Let's plan "${topic}" together in Backlog draft ${id} (it is open in the user's Proposed plan dialog, and empty for now).

How to run this:
- Interview me. Each turn, ask the one or two questions that most change the plan, never a long list. Record them on the draft (mcp__backlog__revise ask), and record answers and decisions as they settle (answer, decide).
- After every answer, revise the draft in place (mcp__backlog__revise on ${id}): add, split, merge, re-scope or drop items. Start rough and sharpen it; don't re-propose the whole tree.
- I may edit the draft myself between turns (you'll be told what I changed): build on my edits and don't undo them without asking.
- Quality bar: each story says who it serves and why, a concrete approach, 3–6 testable acceptance criteria and an estimate. Fold trivial pieces into the story they belong to. No ceremony items ("write tests", "update docs") unless that is the deliverable. No filler.
- When the plan is solid and the open questions are settled, say so plainly and point me to Accept in the dialog (or /backlog accept ${id}). Don't create anything on the board yourself.

Start by restating the goal in one sentence as you understand it, sketch a first rough shape in the draft, and ask your first question.`

const workPrompt = (i: Item) => i.kind === 'epic'
  ? `Work on epic ${i.id}: ${i.title}. Read it with mcp__backlog__show, then work through its open children in order the usual way (show, in_progress, implement, tick criteria, comment, review). When they are all done, tell me it is ready to close; don't close it yourself.`
  : `Work on ${i.id}: ${i.title}. Read it with mcp__backlog__show first, set it to in_progress, implement it, tick each acceptance criterion you verified (update \`met\`), then comment with what you changed and move it to review.${branchHint(i)}`

const nextPrompt = `Pick the next item to work on from the Backlog tracker: call mcp__backlog__summary, choose the highest-priority unblocked story, task or bug (in_progress first, then todo), explain the choice in one line, and start working on it the usual way (show, set in_progress, implement, tick the acceptance criteria you verified, comment, move to review).`

let storage: 'home' | 'project' = 'home'
let webPort = 4747
let queue: Promise<unknown> = Promise.resolve()
let lastMtime = 0
// What this turn did, for the end-of-turn nudge: files Claude edited, and whether it touched the board.
const turnEdits = new Set<string>()
let boardTouched = false
const EDIT_TOOLS = ['Edit', 'Write', 'MultiEdit', 'NotebookEdit']
// Git scanning: when this session last looked, and the commits Claude itself made (so they read as Claude's).
let gitSince: string | undefined
const claudeCommits = new Set<string>()
let scanning: Promise<string[]> | undefined
// Claude's git commands in flight: the background scan waits them out, so it can't claim their commits for the user.
let gitInFlight = 0
let pollCount = 0
const HISTORY_LIMIT = 20

async function now($: $) {
  return new Date(await $.clock.now()).toISOString()
}

async function locate($: $): Promise<string> {
  const known = await read($, pathAtom)
  if (known) return known
  const root = await $.session.root()
  let path: string
  if (storage === 'project') {
    path = `${root}/.backlog/board.json`
    const ignore = `${root}/.backlog/.gitignore`
    if (!(await $.fs.exists(ignore))) await $.fs.write(ignore, '# Backlog data: kept out of git.\n*\n')
  } else {
    const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE')) ?? root
    path = `${home}/.claude/backlog/${slugOf(root)}/board.json`
  }
  await update($, pathAtom, () => path)
  await registerProject($, root, path).catch(() => undefined)
  return path
}

/** Records the board in ~/.claude/backlog/projects.json so the web app finds it, whichever storage it uses. */
async function registerProject($: $, root: string, path: string) {
  const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE'))
  if (!home) return
  const file = `${home}/.claude/backlog/projects.json`
  let registry: Record<string, { root: string; path: string }> = {}
  if (await $.fs.exists(file)) {
    try { registry = JSON.parse(await $.fs.read(file)) } catch { registry = {} }
  }
  const id = projectId(root, path)
  if (registry[id]?.path === path && registry[id]?.root === root) return
  registry[id] = { root, path }
  await $.fs.write(file, JSON.stringify(registry, null, 2) + '\n')
}

/** The id the web app knows a board by: its folder under ~/.claude/backlog, or `<slug>@repo` for in-repo storage. */
function projectId(root: string, path: string) {
  const folder = path.split('/').at(-2)
  return folder === '.backlog' || !folder ? `${slugOf(root)}@repo` : folder
}

// ---------- web app ----------

const webUrl = () => `http://127.0.0.1:${webPort}`

async function webRunning($: $) {
  try {
    return (await $.http.fetch(`${webUrl()}/api/projects`)).ok
  } catch {
    return false
  }
}

const shellQuote = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`

/** Starts the web server detached, so it serves every project and outlives this session; reuses one already running. */
async function startWeb($: $): Promise<'running' | 'started'> {
  if (await webRunning($)) return 'running'
  const server = `${$.plugin.root}/web/server.ts`
  await $.process.run(['sh', '-c', `nohup node --no-warnings ${shellQuote(server)} --port ${webPort} >/dev/null 2>&1 &`], { timeoutMs: 5000 })
  for (let n = 0; n < 20; n++) {
    if (await webRunning($)) return 'started'
    await $.clock.sleep(150)
  }
  throw new Error(`the web server did not start on port ${webPort}; try: node ${server} --port ${webPort}`)
}

async function openBrowser($: $, url: string) {
  const { stdout } = await $.process.run(['uname', '-s']).catch(() => ({ stdout: '' }))
  const opener = stdout.trim() === 'Darwin' ? 'open' : 'xdg-open'
  await $.process.run(['sh', '-c', `${opener} ${shellQuote(url)} >/dev/null 2>&1 &`], { timeoutMs: 5000 }).catch(() => undefined)
}

async function stopWeb($: $): Promise<string> {
  const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE'))
  const file = `${home}/.claude/backlog/web.json`
  if (!(await webRunning($))) return 'The web app is not running.'
  if (!(await $.fs.exists(file))) return `Something answers on port ${webPort}, but it has no web.json; stop it by hand.`
  const { pid } = JSON.parse(await $.fs.read(file)) as { pid: number }
  await $.process.run(['kill', String(pid)])
  for (let n = 0; n < 10; n++) {
    if (!(await webRunning($))) return 'Stopped the web app.'
    await $.clock.sleep(100)
  }
  return `Sent stop to process ${pid}, but port ${webPort} still answers.`
}

async function webCommand($: $, arg: string): Promise<string> {
  if (arg === 'stop') return stopWeb($)
  const path = await locate($)
  const root = await $.session.root()
  const how = await startWeb($)
  const url = `http://localhost:${webPort}/#project=${encodeURIComponent(projectId(root, path))}`
  await openBrowser($, url)
  return `${how === 'running' ? 'Opened' : 'Started and opened'} the web app: ${url}  (/backlog web stop to shut it down)`
}

function slugOf(root: string) {
  return root.replace(/[^A-Za-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'root'
}

async function loadFromDisk($: $, path: string): Promise<Board> {
  const root = await $.session.root()
  if (!(await $.fs.exists(path))) return emptyBoard(root)
  const raw = await $.fs.read(path)
  try {
    const parsed = JSON.parse(raw) as Board
    if (!Array.isArray(parsed.items)) throw new Error('no items')
    const board = migrate(parsed)
    lastMtime = (await $.fs.stat(path)).mtimeMs
    return board
  } catch {
    await $.fs.write(`${path}.corrupt-${await $.clock.now()}.json`, raw)
    $.ui.toast('Backlog: board.json was unreadable; saved a copy and started a new board.')
    return emptyBoard(root)
  }
}

async function publish($: $, board: Board) {
  await update($, boardAtom, () => board)
  const active = board.items.filter(i => i.status === 'in_progress')
  const open = board.items.filter(i => !isClosed(i.status) && i.kind !== 'epic' && i.kind !== 'milestone')
  // The band says all this and more; the status line is for when the band is hidden.
  if (board.items.length === 0 || !(await read($, bandHiddenAtom))) return $.ui.status(undefined)
  const head = active[0] ? `◐ ${active[0].id} ${active[0].title.slice(0, 40)}` : '○ nothing in progress'
  $.ui.status(`${head} · ${open.length} open${active.length > 1 ? ` · ${active.length} active` : ''}`)
}

const historyPath = (path: string) => path.replace(/board\.json$/, 'history.json')

async function loadHistory($: $, path: string): Promise<Change[]> {
  const file = historyPath(path)
  if (!(await $.fs.exists(file))) return []
  try {
    const list = JSON.parse(await $.fs.read(file)) as Change[]
    return Array.isArray(list) ? list : []
  } catch {
    return []
  }
}

async function reload($: $) {
  const path = await locate($)
  const board = await loadFromDisk($, path)
  await publish($, board)
  const history = await loadHistory($, path)
  await update($, lastChangeAtom, () => history.at(-1)?.label ?? null)
  return board
}

type Mutation<T> = { board: Board; out: T; label?: string }

/**
 * Read-modify-write against the file, serialized, so other sessions' edits are
 * not lost. Every change keeps the board before it in history.json for undo.
 */
function mutate<T>($: $, fn: (board: Board, at: string) => Mutation<T>, by: 'user' | 'claude' = 'user'): Promise<T> {
  const run = queue.then(async () => {
    const path = await locate($)
    const board = await loadFromDisk($, path)
    const at = await now($)
    const { board: changed, out, label = 'change' } = fn(board, at)
    if (by === 'claude') boardTouched = true
    if (changed !== board) {
      const next = stamp(board, changed, at, await $.session.id(), by)
      const text = serialize(next)
      const history = [...(await loadHistory($, path)), { at, label, before: board, after: contentPrint(next) }]
      await $.fs.write(historyPath(path), JSON.stringify(history.slice(-HISTORY_LIMIT)))
      await $.fs.write(path, text)
      lastMtime = (await $.fs.stat(path)).mtimeMs
      await update($, lastChangeAtom, () => label)
      await publish($, next)
    } else {
      await publish($, board)
    }
    return out
  })
  queue = run.catch(() => undefined)
  return run
}

/** Restores the board from before the latest change; refuses when the board moved on since, unless forced. */
function undo($: $, force = false, by: 'user' | 'claude' = 'user'): Promise<string> {
  if (by === 'claude') boardTouched = true
  const run = queue.then(async () => {
    const path = await locate($)
    const history = await loadHistory($, path)
    const last = history.at(-1)
    if (!last) return 'Nothing to undo.'
    const current = await loadFromDisk($, path)
    if (!force && contentPrint(current) !== last.after && fingerprint(serialize(current)) !== last.after)
      return `The board changed after "${last.label}" (another session, or a hand edit). Run /backlog undo force to restore it anyway.`
    const rest = history.slice(0, -1)
    const entry = { at: await now($), author: by, session: await $.session.id(), text: `undid "${last.label}"` }
    const restored: Board = { ...last.before, log: [...(current.log ?? []), entry].slice(-50) }
    await $.fs.write(historyPath(path), JSON.stringify(rest))
    await $.fs.write(path, serialize(restored))
    lastMtime = (await $.fs.stat(path)).mtimeMs
    await update($, lastChangeAtom, () => rest.at(-1)?.label ?? null)
    await publish($, restored)
    return `Undid: ${last.label}`
  })
  queue = run.catch(() => undefined)
  return run
}

function removeItem($: $, id: string, cascade: boolean): Promise<string> {
  return mutate($, board => {
    const r = deleteItem(board, id, cascade)
    return r.ok
      ? { board: r.value.board, out: `Deleted ${r.value.removed.join(', ')}`, label: `delete ${r.value.removed.join(', ')}` }
      : { board, out: r.error }
  })
}

async function deleteFromPane($: $, id: string, cascade: boolean) {
  await update($, confirmAtom, () => null)
  await closeItem($)
  $.ui.toast(`${await removeItem($, id, cascade)}. Press u to undo.`)
}

async function statusFromPane($: $, id: string, status: Status) {
  const before = resolveId((await read($, boardAtom)) ?? emptyBoard(''), id)
  const text = await setStatus($, id, status)
  const board = await read($, boardAtom)
  // Reviewing is a queue: after approving or sending back one, the next waiting item opens.
  const wasReady = before !== undefined && status === 'done' && (before.kind === 'epic' || before.kind === 'milestone')
  const queue = !board ? []
    : before?.status === 'review' ? sortItems(board.items.filter(i => i.status === 'review' && i.kind !== 'epic' && i.kind !== 'milestone'))
    : wasReady ? closable(board)
    : []
  if (queue.length && (await read($, selectedAtom)) === before!.id) {
    if (wasReady) await update($, viewAtom, () => (queue[0]!.kind === 'milestone' ? 'milestones' : 'epics'))
    await update($, selectedAtom, () => queue[0]!.id)
    await update($, expandedAtom, () => null)
  }
  const done = text.includes('→') ? `${text.replace(status, STATUS_LABEL[status].toLowerCase())} · u to undo` : text
  const what = wasReady ? 'next to close' : 'next to review'
  $.ui.toast(queue.length ? `${done} · ${what}: ${queue[0]!.id} (${queue.length} left)` : done)
}

function moveFrom($: $, id: string, move: Move): Promise<string> {
  return mutate($, (board, at) => {
    const r = moveItem(board, id, move, at, 'user')
    if (!r.ok) return { board, out: r.error }
    if (!r.value.moved) return { board, out: `${r.value.item.id} is already at the ${move === 'up' || move === 'top' ? 'top' : 'bottom'}.` }
    return { board: r.value.board, out: `Moved ${r.value.item.id} ${move}`, label: `move ${r.value.item.id} ${move}` }
  })
}

function toggleCriterion($: $, id: string, n: number, met: boolean) {
  return mutate($, (board, at) => {
    const r = updateItem(board, id, met ? { met: [n] } : { unmet: [n] }, at, 'user')
    return r.ok ? { board: r.value.board, out: null, label: `${met ? 'tick' : 'untick'} ${id} #${n}` } : { board, out: null }
  })
}

/** Opens the board pane, optionally on a view and with a card already selected (its parent expanded when it has one). */
async function openBoard($: $, view?: View, select?: string) {
  if (view) await update($, viewAtom, () => view)
  if (select) {
    await update($, confirmAtom, () => null)
    await update($, editingAtom, () => false)
    await update($, queryAtom, () => '')
    await update($, selectedAtom, () => select)
    await update($, expandedAtom, () => null)
  }
  await $.ui.open({ id: PANE, title: 'Backlog', focus: true })
}

async function setBand($: $, hidden: boolean) {
  await update($, bandHiddenAtom, () => hidden)
  await $.store.set('bandHidden', hidden)
  const board = await read($, boardAtom)
  if (board) await publish($, board)
}

/** Saves a plan as a draft on the board and opens it for the user. */
async function propose($: $, items: ItemInput[], topic?: string): Promise<string> {
  const id = await mutate($, (board, at) => {
    const r = addDraft(board, items, at, topic?.trim() || undefined)
    return { board: r.board, out: r.draft.id, label: `draft ${r.draft.id}` }
  }, 'claude')
  await openDraft($, id)
  return id
}

/**
 * Queues a prompt to start once the current hook is done: a slash command or a
 * press can't submit while it holds the turn, so it goes out a moment later.
 */
function submitSoon($: $, text: string) {
  $.clock.after(50, () => void $.prompt.submit({ text }).catch(() => undefined))
}

/**
 * Finds TODO/FIXME/HACK/XXX comments in the repository (tracked files plus
 * untracked ones git doesn't ignore) and proposes the new ones as a draft.
 */
async function importTodos($: $): Promise<string> {
  const run = (argv: string[]) => $.process.run(argv, { timeoutMs: 20_000 })
  const inside = await run(['git', 'rev-parse', '--is-inside-work-tree']).catch(() => undefined)
  if (!inside || inside.exitCode !== 0) return 'This project is not a git repository, so there is nothing to scan (the scan follows .gitignore).'
  const grep = await run(['git', 'grep', '-n', '-I', '--untracked', '--exclude-standard', '-E', TODO_PATTERN])
  if (grep.exitCode > 1) return `git grep failed: ${grep.stderr.trim().split('\n')[0]}`
  const todos = parseTodos(grep.stdout)
  const items = todoItems(await reload($), todos)
  if (!todos.length) return 'No TODO, FIXME, HACK or XXX comments found.'
  if (!items.length) return `All ${todos.length} TODO comment${todos.length === 1 ? ' is' : 's are'} already on the board or in a draft.`
  const id = await propose($, items, `TODO comments (${items.length})`)
  return `Found ${todos.length} comment${todos.length === 1 ? '' : 's'}; ${items.length} new. Proposed as ${id}: untick what you don't want and accept.${grep.isStdoutTruncated ? ' (Output was cut short; run again after accepting.)' : ''}`
}

/**
 * One line for a Backlog tool call in the transcript, instead of its raw
 * arguments: what was asked, in the board's own words.
 */
function toolLine(tool: string, input: unknown): string {
  const a = (input ?? {}) as Record<string, unknown>
  const list = (v: unknown) => (Array.isArray(v) ? v as Record<string, unknown>[] : [])
  const titles = (v: unknown) => list(v).map(i => String(i.title ?? '')).filter(Boolean)
  const first = (xs: string[], n = 3) => xs.slice(0, n).map(t => `"${t}"`).join(', ') + (xs.length > n ? ` +${xs.length - n}` : '')
  const ids = [...(Array.isArray(a.ids) ? a.ids as string[] : []), ...(a.id ? [String(a.id)] : [])].join(', ')
  switch (tool.replace(/^mcp__backlog__/, '')) {
    case 'summary': return 'summary'
    case 'list': return `list ${[a.view, a.kind, a.status, a.text && `"${a.text}"`].filter(Boolean).join(' · ') || 'open items'}`
    case 'show': return `show ${a.id ?? ''}`
    case 'create': return `create ${list(a.items).length} item${list(a.items).length === 1 ? '' : 's'}: ${first(titles(a.items))}`
    case 'propose': return `propose ${list(a.items).length} item${list(a.items).length === 1 ? '' : 's'} for review${a.topic ? ` · ${a.topic}` : `: ${first(titles(a.items), 2)}`}`
    case 'revise': {
      const parts = [
        list(a.add).length && `+${list(a.add).length}`, list(a.update).length && `~${list(a.update).length}`,
        Array.isArray(a.remove) && a.remove.length && `−${a.remove.length}`, Array.isArray(a.ask) && a.ask.length && `${a.ask.length} asked`,
        list(a.answer).length && `${list(a.answer).length} answered`, Array.isArray(a.decide) && a.decide.length && `${a.decide.length} decided`,
      ].filter(Boolean)
      return `revise ${a.draft ?? 'draft'}${parts.length ? `: ${parts.join(' ')}` : ''}`
    }
    case 'update': {
      const parts = [
        a.status && `→ ${a.status}`, a.priority && `priority ${a.priority}`, a.title && 'title',
        a.met && `✓ ${Array.isArray(a.met) ? a.met.join(',') : a.met}`, a.met_all && '✓ all', a.move && `move ${a.move}`,
        a.comment && 'note', a.acceptance && 'criteria', a.description && 'description',
      ].filter(Boolean)
      return `update ${ids}${parts.length ? ` ${parts.join(' · ')}` : ''}`
    }
    case 'delete': return `delete ${a.id ?? ''}${a.cascade ? ' and its children' : ''}`
    case 'undo': return 'undo the last change'
    default: return tool
  }
}

/** Writes the board as Markdown into the project (ROADMAP.md unless a path is given). */
async function exportMarkdown($: $, arg: string): Promise<string> {
  const parts = arg.split(/\s+/).filter(Boolean)
  const open = parts.includes('--open')
  const target = parts.find(p => !p.startsWith('--')) ?? 'ROADMAP.md'
  const root = await $.session.root()
  const path = target.startsWith('/') ? target : `${root}/${target}`
  const board = await reload($)
  const date = new Date(await $.clock.now()).toISOString().slice(0, 10)
  await $.fs.write(path, toMarkdown(board, { date, open }))
  return `Wrote ${path.replace(`${root}/`, '')} (${board.items.filter(i => !open || !isClosed(i.status)).length} items${open ? ', open only' : ''}).`
}

/**
 * Mirrors open work items to GitHub Issues with gh: creates missing issues,
 * edits changed ones, and closes or reopens them with their items. Without
 * --yes it only says what it would do, since issues are published.
 */
async function exportGithub($: $, apply: boolean): Promise<string> {
  const run = (argv: string[]) => $.process.run(argv, { timeoutMs: 30_000 })
  const repo = await run(['gh', 'repo', 'view', '--json', 'nameWithOwner', '-q', '.nameWithOwner']).catch(() => undefined)
  if (!repo || repo.exitCode !== 0) return 'GitHub export needs the gh CLI, logged in, in a project with a GitHub remote (gh repo view failed).'
  const name = repo.stdout.trim()
  const board = await reload($)
  const plan = planGithub(board)
  const count = `${plan.create.length} to create, ${plan.edit.length} to update, ${plan.close.length} to close, ${plan.reopen.length} to reopen`
  if (!plan.create.length && !plan.edit.length && !plan.close.length && !plan.reopen.length) return `GitHub Issues on ${name} are up to date.`
  if (!apply) {
    const preview = plan.create.slice(0, 8).map(i => `  + ${issueTitle(i)}`)
    return [`Would mirror to ${name}: ${count}.`, ...preview, ...(plan.create.length > 8 ? [`  … and ${plan.create.length - 8} more`] : []),
      'Issues are public on public repos. Run /backlog export github --yes to do it.'].join('\n')
  }
  await run(['gh', 'label', 'create', 'backlog', '--color', '6b7cff', '--description', 'Tracked in Backlog', '--force'])
  const linked = new Map<string, { number: number; url: string; state: 'open' | 'closed' }>()
  const failures: string[] = []
  for (const i of plan.create) {
    const r = await run(['gh', 'issue', 'create', '--title', issueTitle(i), '--body', issueBody(board, i), '--label', 'backlog'])
    const url = r.stdout.trim().split('\n').at(-1) ?? ''
    const number = Number(url.match(/\/issues\/(\d+)/)?.[1])
    if (r.exitCode === 0 && number) linked.set(i.id, { number, url, state: 'open' })
    else failures.push(`${i.id}: ${(r.stderr || r.stdout).trim().split('\n')[0]}`)
  }
  for (const i of plan.edit) {
    const r = await run(['gh', 'issue', 'edit', String(i.github!.number), '--title', issueTitle(i), '--body', issueBody(board, i)])
    if (r.exitCode === 0) linked.set(i.id, { ...i.github!, state: linked.get(i.id)?.state ?? i.github!.state })
    else failures.push(`${i.id}: ${r.stderr.trim().split('\n')[0]}`)
  }
  for (const [list, verb, state] of [[plan.close, 'close', 'closed'], [plan.reopen, 'reopen', 'open']] as const) {
    for (const i of list) {
      const r = await run(['gh', 'issue', verb, String(i.github!.number)])
      if (r.exitCode === 0) linked.set(i.id, { ...(linked.get(i.id) ?? i.github!), state })
      else failures.push(`${i.id}: ${r.stderr.trim().split('\n')[0]}`)
    }
  }
  await mutate($, current => ({
    board: { ...current, items: current.items.map(i => (linked.has(i.id) ? { ...i, github: { ...linked.get(i.id)!, hash: issueHash(current, i) } } : i)) },
    out: null,
    label: `export to GitHub (${linked.size})`,
  }))
  return `Mirrored to ${name}: ${count}.${failures.length ? `\nFailed: ${failures.join('; ')}` : ''}`
}

/** Opens an empty draft for a topic and asks Claude to interview the user into a plan. */
async function startPlanning($: $, topic: string): Promise<string> {
  const id = await mutate($, (board, at) => {
    const r = addDraft(board, [], at, topic.trim())
    return { board: r.board, out: r.draft.id, label: `draft ${r.draft.id}` }
  })
  await openDraft($, id)
  submitSoon($, planPrompt(topic.trim(), id))
  return `Started planning "${topic.trim()}" in ${id}. Claude will interview you and shape the draft; accept it when it's right.`
}

async function openDraft($: $, id: string) {
  await update($, activeDraftAtom, () => id)
  await $.ui.open({ id: PLAN, title: 'Proposed plan', focus: true }).catch(() => undefined)
}

async function draftFor($: $, id?: string) {
  const board = await reload($)
  return findDraft(board, id ?? (await read($, activeDraftAtom)) ?? undefined) ?? findDraft(board)
}

async function acceptProposal($: $, allowScope?: string, id?: string, anyway = false, allowDone = false): Promise<string> {
  const draft = await draftFor($, id)
  if (!draft || draft.status !== 'open') return 'No plan is waiting for review.'
  const open = openQuestions(draft)
  if (open.length && !anyway) return `${draft.id} still has ${open.length} open question${open.length === 1 ? '' : 's'} (${open.map(q => q.text).join(' | ')}). Keep planning, or accept anyway: /backlog accept ${draft.id} --anyway`
  await update($, planConfirmAtom, () => null)
  const kept = withPlanningNotes(keptItems(draft.items as ItemInput[], draft.include), draft)
  if (!kept.length) return discardProposal($, draft.id)
  const text = await mutate($, (current, at) => {
    const grants = !allowScope ? [] : [{ scope: allowScope, what: 'plans' as const, at }, ...(allowDone ? [{ scope: allowScope, what: 'done' as const, at }] : [])]
    const board = allowScope ? { ...current, allow: [...(current.allow ?? []).filter(a => !(a.scope === allowScope && grants.some(g => g.what === a.what))), ...grants] } : current
    const r = createItems(board, kept, at, 'user')
    const ids = r.created.map(i => i.id)
    const out = ids.length ? `Created ${ids.length === 1 ? ids[0] : `${ids[0]} and ${ids.length - 1} more`}${r.errors.length ? ` (skipped: ${r.errors.join('; ')})` : ''}` : r.errors.join('; ')
    const closed = closeDraft(r.created.length ? r.board : board, draft.id, 'accepted', at, ids)
    return { board: closed, out: allowScope ? `${out}. ${allowDone ? `Under ${allowScope}, Claude's plans and its verified work won't need review` : `Plans under ${allowScope} won't need review`} from now on (/backlog revoke ${allowScope} to undo).` : out, label: `accept ${draft.id} (${ids.join(', ')})` }
  })
  await afterClose($, draft.id)
  return text
}

async function discardProposal($: $, id?: string): Promise<string> {
  const draft = await draftFor($, id)
  if (!draft || draft.status !== 'open') return 'No plan is waiting for review.'
  await mutate($, (board, at) => ({ board: closeDraft(board, draft.id, 'discarded', at), out: null, label: `discard ${draft.id}` }))
  await afterClose($, draft.id)
  return `Discarded ${draft.id} (${draft.topic}).`
}

/** After a draft closes, show the next open one, or close the dialog. */
async function afterClose($: $, id: string) {
  const next = openDrafts((await read($, boardAtom)) ?? emptyBoard('')).at(-1)
  if (next) return openDraft($, next.id)
  if ((await read($, activeDraftAtom)) === id) await update($, activeDraftAtom, () => null)
  await $.ui.close({ id: PLAN }).catch(() => undefined)
}

/** The user's own edit to a draft: kept safe from Claude's revisions, and reported to it next turn. */
async function editDraft($: $, id: string, ops: DraftOps) {
  const session = await $.session.id()
  const text = await mutate($, (board, at) => {
    const d = findDraft(board, id)
    if (!d || d.status !== 'open') return { board, out: '' }
    const r = reviseDraft(d, ops, 'user', at, session)
    return { board: r.changes.length ? changeDraft(board, d.id, () => r.draft) : board, out: r.errors.join('; '), label: `${d.id}: your edit` }
  })
  if (text) $.ui.toast(`Backlog: ${text}`)
}

const criteriaFrom = (text: string) => text.split(/\s*\|\s*|\n/).map(c => c.trim()).filter(Boolean)

async function toggleProposed($: $, id: string, n: number) {
  const session = await $.session.id()
  await mutate($, (board, at) => ({
    board: changeDraft(board, id, d => {
      const item = d.items[n]
      const keep = !d.include[n]
      const entry = { at, author: 'user' as const, session, text: `${keep ? 'ticked' : 'unticked'} ${item?.kind ?? 'item'} "${item?.title ?? n + 1}"` }
      return { ...d, updatedAt: at, include: d.include.map((v, k) => (k === n ? keep : v)), log: [...(d.log ?? []), entry].slice(-60) }
    }),
    out: null,
    label: `${id}: toggle item ${n + 1}`,
  }))
}

/** A proposal kept in session state by an earlier version becomes a draft, rather than being lost. */
async function migrateProposal($: $) {
  const old = await read($, proposalAtom)
  if (!old) return
  await mutate($, (board, at) => {
    const r = addDraft(board, old.items as ItemInput[], at)
    const draft = { ...r.draft, include: old.include }
    return { board: changeDraft(r.board, draft.id, () => draft), out: null, label: `draft ${draft.id} (carried over)` }
  }, 'claude')
  await update($, proposalAtom, () => null)
}

async function undoFromPane($: $) {
  $.ui.toast(await undo($))
}

function setStatus($: $, id: string, status: Status, author: 'user' | 'claude' = 'user') {
  return mutate($, (board, at) => {
    const r = updateItem(board, id, { status }, at, author)
    return r.ok ? { board: r.value.board, out: `${r.value.item.id} → ${status}`, label: `${r.value.item.id} → ${status}` } : { board, out: r.error }
  })
}

/**
 * Selecting an epic, story or milestone expands it in the list; selecting one
 * of its members keeps it expanded, so you can walk its children.
 */
async function selectItem($: $, id: string, toggle = true) {
  const wasSelected = (await read($, selectedAtom)) === id
  if (wasSelected && !toggle) return
  await update($, confirmAtom, () => null)
  await update($, editingAtom, () => false)
  await update($, selectedAtom, () => (wasSelected ? null : id))
  const board = await read($, boardAtom)
  const item = board ? resolveId(board, id) : undefined
  const open = board ? resolveId(board, await read($, expandedAtom)) : undefined
  const isContainer = item !== undefined && board !== null && membersOf(board, item).length > 0
  if (isContainer && !(open && membersOf(board!, open).some(m => m.id === item.id))) {
    await update($, expandedAtom, () => (wasSelected ? null : item.id))
  } else if (!(item && open && board && membersOf(board, open).some(m => m.id === item.id))) {
    await update($, expandedAtom, () => null)
  }
}

async function closeItem($: $) {
  await update($, confirmAtom, () => null)
  await update($, expandedAtom, () => null)
  await update($, editingAtom, () => false)
  await update($, selectedAtom, () => null)
}

const beside = (path: string, name: string) => path.replace(/board\.json$/, name)

type WebRequest = { kind: 'idea' | 'work' | 'next'; text?: string; id?: string }

/**
 * Requests from the web app ("Plan with Claude", "Ask Claude to work on it")
 * become prompts in this session. Emptying the inbox first keeps two sessions
 * from both taking the same request, all but in a dead heat.
 */
async function takeInbox($: $, path: string) {
  const file = beside(path, 'inbox.json')
  if (!(await $.fs.exists(file))) return
  let requests: WebRequest[] = []
  try { requests = JSON.parse(await $.fs.read(file)) as WebRequest[] } catch { requests = [] }
  if (!Array.isArray(requests) || !requests.length) return
  await $.fs.write(file, '[]')
  const board = (await read($, boardAtom)) ?? (await reload($))
  for (const r of requests) {
    const item = r.id ? resolveId(board, r.id) : undefined
    const text = r.kind === 'idea' && r.text?.trim() ? ideaPrompt(r.text.trim())
      : r.kind === 'work' && item ? workPrompt(item)
      : r.kind === 'next' ? nextPrompt
      : undefined
    if (!text) continue
    $.ui.toast(`Backlog: ${r.kind === 'idea' ? 'planning an idea' : r.kind === 'work' ? `working on ${item!.id}` : 'picking the next item'} (from the web app)`)
    void $.prompt.submit({ text })
  }
}

/**
 * Reads git for commits that name items and branches that carry their ids, and
 * updates the items' code records. Incremental within a session; outside a git
 * repository it does nothing.
 */
function scanGit($: $, background = false): Promise<string[]> {
  if (background && gitInFlight > 0) return Promise.resolve([])
  if (scanning) return scanning
  scanning = (async () => {
    const run = (argv: string[]) => $.process.run(argv, { timeoutMs: 10_000 })
    const inside = await run(['git', 'rev-parse', '--is-inside-work-tree']).catch(() => undefined)
    if (!inside || inside.exitCode !== 0) return []
    const started = new Date(await $.clock.now() - 60_000).toISOString()
    const range = gitSince ? [`--since=${gitSince}`] : ['-n', '400']
    const log = await run(['git', 'log', '--all', '--source', ...range, '--format=%H%x1f%S%x1f%an%x1f%aI%x1f%s%x1f%b%x1e'])
    const commits: GitCommit[] = log.exitCode !== 0 ? [] : log.stdout.split('\x1e').map(r => r.replace(/^\n/, '')).filter(Boolean).map(r => {
      const [hash = '', source = '', author = '', at = '', subject = '', body = ''] = r.split('\x1f')
      return { hash: hash.trim(), branch: source.replace(/^refs\/(heads|remotes)\//, '') || undefined, author, at, subject, body }
    }).filter(c => /^[0-9a-f]{40}$/.test(c.hash))
    const refs = await run(['git', 'for-each-ref', '--format=%(refname:short)', 'refs/heads', 'refs/remotes'])
    const branches = refs.exitCode === 0 ? refs.stdout.split('\n').map(b => b.trim()).filter(b => b && !b.endsWith('/HEAD')) : undefined
    gitSince = started
    if (!commits.length && !branches) return []
    return mutate($, (board, at) => {
      const r = applyGit(board, commits, branches, at, c => (claudeCommits.has(c.hash) ? 'claude' : 'user'))
      return { board: r.board, out: r.linked, label: 'link git history' }
    }, 'claude')
  })().finally(() => { scanning = undefined })
  return scanning
}

/**
 * Starts an item on its own branch: reuses one carrying its id, else creates
 * one from the current branch. With uncommitted changes it explains instead,
 * unless told to carry them over. Never stashes or discards anything.
 */
async function startOnBranch($: $, ref: string, anyway = false): Promise<string> {
  const board = await reload($)
  const item = resolveId(board, ref)
  if (!item) return `No item "${ref}".`
  const run = (argv: string[]) => $.process.run(argv, { timeoutMs: 10_000 })
  const inside = await run(['git', 'rev-parse', '--is-inside-work-tree']).catch(() => undefined)
  if (!inside || inside.exitCode !== 0) return 'This project is not a git repository.'
  const lines = (r: { stdout: string }) => r.stdout.split('\n').map(l => l.trim()).filter(Boolean)
  const current = (await run(['git', 'branch', '--show-current'])).stdout.trim()
  const local = lines(await run(['git', 'for-each-ref', '--format=%(refname:short)', 'refs/heads']))
  const remote = lines(await run(['git', 'for-each-ref', '--format=%(refname:short)', 'refs/remotes'])).filter(b => !b.endsWith('/HEAD'))
  const dirty = lines(await run(['git', 'status', '--porcelain'])).length
  const plan = planBranch(item, { current, local, remote, dirty }, anyway)
  if (plan.action === 'ask') return `${item.id}: not switching. ${plan.reason} (/backlog branch ${item.id} --anyway)`
  if (plan.action !== 'stay') {
    const r = await run(plan.action === 'create' ? ['git', 'switch', '-c', plan.name] : ['git', 'switch', plan.name])
    if (r.exitCode !== 0) return `git switch failed: ${(r.stderr || r.stdout).trim().split('\n')[0]}`
  }
  if (item.status !== 'in_progress' && !isClosed(item.status)) await setStatus($, item.id, 'in_progress')
  await scanGit($).catch(() => undefined)
  return plan.action === 'create' ? `Created branch ${plan.name} for ${item.id} and started it.`
    : plan.action === 'switch' ? `Switched to ${plan.name} for ${item.id} and started it.`
    : `Already on ${plan.name}; ${item.id} is in progress.`
}

async function branchFromPane($: $, id: string) {
  $.ui.toast(await startOnBranch($, id))
}

/** Picks up edits other sessions made to the same board. */
async function poll($: $) {
  const path = await locate($)
  // Tell the web app a Claude session is here, and take any requests it left.
  await $.fs.write(beside(path, 'presence.json'), JSON.stringify({ session: await $.session.id(), at: await now($) }))
  await takeInbox($, path)
  if (pollCount++ % 12 === 0) await scanGit($, true).catch(() => undefined)
  if (!(await $.fs.exists(path))) return
  const { mtimeMs } = await $.fs.stat(path)
  if (mtimeMs !== lastMtime) await reload($)
}

