export const register: Register = (on, options) => {
  storage = options.storage === 'project' ? 'project' : 'home'
  webPort = typeof options.webPort === 'number' && options.webPort > 0 ? options.webPort : 4747

  // ---------- session ----------

  on('session.start', async ($, e, next) => {
    // A refused registration (a name another command took) must not stop the rest.
    const results = await Promise.allSettled([
      $.command.register({
        name: 'backlog',
        description: 'Backlog: open the project board, or manage items (/backlog help)',
        argumentHint: '[help | list | add | bug | story | epic | milestone | show | start | review | done | block | rm | next | where]',
      }),
      $.command.register({
        name: 'idea',
        description: 'Backlog: turn an idea into an epic, stories and tasks',
        argumentHint: '<idea>',
      }),
      registerTools($),
    ])
    for (const r of results) if (r.status === 'rejected') $.ui.toast(`Backlog: ${String(r.reason)}`)
    await reload($)
    await migrateProposal($).catch(() => undefined)
    if ((await $.store.get('bandHidden')) === true) await update($, bandHiddenAtom, () => true)
    if (!(await read($, seenAtom))) {
      const started = await now($)
      await update($, seenAtom, () => started)
    }
    $.clock.every(5000, () => void poll($).catch(() => undefined))
    return next(e)
  })

  // Keeps Claude in sync: what the user (or another session) changed on the board
  // since the last prompt rides along with the next one, as context only the model reads.
  on('prompt.submit', async ($, e, next) => {
    turnEdits.clear()
    boardTouched = false
    const seen = await read($, seenAtom)
    const at = await now($)
    let context = e.context
    try {
      if (seen) {
        const board = await reload($)
        const changes = digest(board, seen, await $.session.id())
        if (changes) context = [...(e.context ?? []), changes]
      }
    } finally {
      await update($, seenAtom, () => at)
    }
    return next(context === e.context ? e : { ...e, context })
  })

  // Note the files this turn edits, for the nudge below.
  on('tool.call', async ($, e, next) => {
    const result = await next(e)
    const tool = String(e.tool)
    if (EDIT_TOOLS.includes(tool) && result.deny === undefined && result.isError !== true) {
      const args = e as unknown as { file_path?: string; notebook_path?: string }
      turnEdits.add(args.file_path ?? args.notebook_path ?? tool)
    }
    return result
  })

  // A commit that names items is noted on them, so the board points at the code.
  // Any git command Claude runs may have made commits or branches: look again.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const isGit = /\bgit\b/.test(e.command)
    if (isGit) gitInFlight++
    let result
    try {
      result = await next(e)
    } finally {
      if (isGit) gitInFlight--
    }
    if (!isGit || result.deny !== undefined || result.isError === true) return result
    try {
      if (/\bcommit\b/.test(e.command)) {
        const head = await $.process.run(['git', 'rev-parse', 'HEAD'], { timeoutMs: 5000 })
        const hash = head.exitCode === 0 ? head.stdout.trim() : ''
        if (hash) {
          claudeCommits.add(hash)
          // If a scan got there first and stamped it as the user's, put it right.
          const session = await $.session.id()
          await mutate($, board => {
            const claimed = claimCommit(board, hash, session)
            return { board: claimed, out: null, label: `claim commit ${hash.slice(0, 7)}` }
          }, 'claude')
        }
      }
      const linked = await scanGit($)
      if (linked.length) $.ui.toast(`Backlog: linked ${linked.join(', ')} to their commits`)
    } catch { /* not a git repo, or git missing: nothing to link */ }
    return result
  })

  // When a turn changed files but left the board alone, suggest (never force) catching it up.
  on('classic.Stop', async ($, e, next) => {
    const result = await next(e)
    if (!turnEdits.size || boardTouched) return result
    const board = await read($, boardAtom)
    if (!board?.items.length) return result
    const doing = sortItems(board.items.filter(i => i.status === 'in_progress' && i.kind !== 'epic' && i.kind !== 'milestone'))[0]
    const files = turnEdits.size === 1 ? '1 file' : `${turnEdits.size} files`
    const text = doing
      ? `Update ${doing.id} on the board: tick the criteria you verified and note what changed in those ${files}`
      : `Add what you just changed (${files}) to the board, or link it to the item it belongs to`
    turnEdits.clear()
    await $.prompt.suggest({ text }).catch(() => undefined)
    return result
  })

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    return { sections: [...composed.sections, { id: `${PLUGIN}:tracker`, text: GUIDE, scope: 'session' as const }] }
  })

  const answer = (text: string) => ({ result: text })

  on('tool.call', { tool: 'mcp__backlog__summary' }, async $ => answer(summary(await reload($))))

  on('tool.call', { tool: 'mcp__backlog__list' }, async ($, e) => {
    const board = await reload($)
    const args = e as unknown as Filter & { view?: View }
    const items = args.view && VIEWS.includes(args.view) ? viewItems(board, args.view) : filterItems(board, args)
    return answer(items.length ? items.map(i => line(board, i)).join('\n') : 'No matching items.')
  })

  on('tool.call', { tool: 'mcp__backlog__show' }, async ($, e) => {
    const board = await reload($)
    if (/^d-?\d+$/i.test(String(e.id ?? '').trim())) {
      const d = findDraft(board, String(e.id))
      if (!d) return answer(`No draft "${String(e.id)}".`)
      const depth = planDepths(d.items as ItemInput[])
      const rows = d.items.map((it, n) => `${'  '.repeat(depth[n] ?? 0)}${d.include[n] ? '[x]' : '[ ]'} ${it.ref} · ${it.kind} · ${it.title}${it.points !== undefined ? ` (${it.points}pt)` : ''}${it.acceptance?.length ? `\n${'  '.repeat((depth[n] ?? 0) + 2)}criteria: ${it.acceptance.join(' | ')}` : ''}${d.userEdited?.[it.ref!]?.length ? `  (user edited: ${d.userEdited[it.ref!]!.join(', ')})` : ''}`)
      const qs = (d.questions ?? []).map(q => `- ${q.id} ${q.text}${q.answer ? ` → ${q.answer}` : ' (open)'}`)
      const ds = (d.decisions ?? []).map(x => `- ${x.text} (${x.author})`)
      return answer([`${d.id} · ${d.topic} · ${d.status}`, ...(rows.length ? rows : ['(no items yet)']),
        ...(qs.length ? ['', 'Questions:', ...qs] : []), ...(ds.length ? ['', 'Decisions:', ...ds] : []),
        ...(d.log?.length ? ['', 'Recent edits:', ...d.log.slice(-8).map(c => `- ${c.author}: ${c.text}`)] : [])].join('\n'))
    }
    const item = resolveId(board, String(e.id ?? ''))
    return answer(item ? detail(board, item, { nowMs: await $.clock.now() }) : `No item "${String(e.id)}".`)
  })

  on('tool.call', { tool: 'mcp__backlog__create' }, async ($, e) => {
    const items = (Array.isArray(e.items) ? e.items : []) as ItemInput[]
    const text = await mutate($, (board, at) => {
      const r = createItems(board, items, at)
      const lines = r.created.map(i => `created ${line(r.board, i)}`)
      if (r.errors.length) lines.push('', 'Not created:', ...r.errors.map(x => `- ${x}`))
      return { board: r.created.length ? r.board : board, out: lines.join('\n') || 'Nothing to create.', label: `create ${r.created.map(i => i.id).join(', ')}` }
    }, 'claude')
    return answer(text)
  })

  on('tool.call', { tool: 'mcp__backlog__propose' }, async ($, e) => {
    const items = (Array.isArray(e.items) ? e.items : []) as ItemInput[]
    if (!items.length) return answer('Nothing to propose.')
    // Inside an epic or milestone the user approved plans for: create now, and say so.
    const allowed = allowedFor((await reload($)), items)
    if (allowed) {
      const text = await mutate($, (board, at) => {
        const r = createItems(board, items, at)
        const lines = r.created.map(i => `created ${line(r.board, i)}`)
        if (r.errors.length) lines.push('', 'Not created:', ...r.errors.map(x => `- ${x}`))
        return { board: r.created.length ? r.board : board, out: lines.join('\n'), label: `create ${r.created.map(i => i.id).join(', ')} (approved under ${allowed})` }
      }, 'claude')
      $.ui.toast(`Backlog: added ${items.length} item${items.length === 1 ? '' : 's'} under ${allowed} (you approved plans there)`)
      return answer(`${text}\n\nCreated without review: the user gave standing approval for plans under ${allowed}. Tell them what you added.`)
    }
    const id = await propose($, items, typeof e.topic === 'string' ? e.topic : undefined)
    return answer(`Proposed ${items.length} item${items.length === 1 ? '' : 's'} as draft ${id} for review. The user is reviewing it in the "Proposed plan" dialog; nothing is on the board until they accept (they can also run /backlog accept ${id}). You'll see what they kept in your next turn's board changes.`)
  })

  on('tool.call', { tool: 'mcp__backlog__revise' }, async ($, e) => {
    const args = e as unknown as DraftOps & { draft?: string }
    const session = await $.session.id()
    const text = await mutate($, (board, at) => {
      const d = findDraft(board, args.draft)
      if (!d || d.status !== 'open') return { board, out: args.draft ? `No open draft "${args.draft}".` : 'No open draft. Use propose to start one.' }
      const r = reviseDraft(d, args, 'claude', at, session)
      const lines = [`${d.id} "${d.topic}":`, ...(r.changes.length ? r.changes.map(c => `  ${c}`) : ['  no changes'])]
      if (r.conflicts.length) lines.push('Kept the user\'s version (conflicts):', ...r.conflicts.map(c => `  ! ${c}`))
      if (r.errors.length) lines.push('Problems:', ...r.errors.map(x => `  - ${x}`))
      return { board: r.changes.length ? changeDraft(board, d.id, () => r.draft) : board, out: lines.join('\n'), label: `revise ${d.id}` }
    }, 'claude')
    return answer(text)
  })

  on('tool.call', { tool: 'mcp__backlog__update' }, async ($, e) => {
    const { id, ids, move: rawMove, approved_by_user: userAsked, tool: _t, tool_use_id: _u, ...patch } = e as unknown as ItemPatch & { id?: string; ids?: string[]; move?: string; approved_by_user?: boolean; tool: string; tool_use_id: string }
    const move = MOVES.includes(rawMove as Move) ? (rawMove as Move) : undefined
    // Callers sometimes send number lists as text ("1, 2" or "[1,2]"); read the numbers out.
    for (const k of ['met', 'unmet'] as const) {
      const v = patch[k] as unknown
      if (v !== undefined && !Array.isArray(v)) patch[k] = String(v).match(/\d+/g)?.map(Number) ?? []
      else if (Array.isArray(v)) patch[k] = v.map(Number)
    }
    if (typeof patch.met_all === 'string') patch.met_all = patch.met_all === 'true'
    const targets = [...(ids ?? []), ...(id ? [id] : [])]
    if (!targets.length) return answer('Give `id` or `ids`.')
    const text = await mutate($, (board, at) => {
      const out: string[] = []
      let current = board
      for (const t of targets) {
        // Done is the user's call, unless they gave standing approval for this epic or milestone.
        let mine: ItemPatch = patch
        let under: string | undefined
        const before = resolveId(current, t)
        if (patch.status === 'done' && before && before.status !== 'done') {
          const gate = gateDone(current, before, userAsked === true)
          if (gate.refuse) { out.push(gate.refuse); continue }
          if (gate.status || gate.note) mine = { ...patch, ...(gate.status ? { status: gate.status } : {}), comment: [patch.comment, gate.note].filter(Boolean).join('\n') }
          under = gate.under
        }
        const r = updateItem(current, t, mine, at, 'claude')
        if (r.ok && under) {
          const marked = { ...r.value.item, closedUnder: under }
          r.value = { board: { ...r.value.board, items: r.value.board.items.map(i => (i.id === marked.id ? marked : i)) }, item: marked }
        }
        if (r.ok && move) {
          const m = moveItem(r.value.board, r.value.item.id, move, at)
          if (m.ok) r.value = { board: m.value.board, item: m.value.item }
        }
        if (r.ok) {
          current = r.value.board
          out.push(`updated ${line(current, r.value.item)}`)
          const a = acceptanceProgress(r.value.item)
          if (a?.open.length && r.value.item.status === 'review')
            out.push(`  note: acceptance criteria ${a.open.map(n => `#${n}`).join(', ')} are not ticked. Tick the ones you verified with met, or say why they are open.`)
        }
        else out.push(`${t}: ${r.error}`)
      }
      return { board: current, out: out.join('\n'), label: `update ${targets.join(', ')}` }
    }, 'claude')
    return answer(text)
  })

  on('tool.call', { tool: 'mcp__backlog__undo' }, async ($, e) => answer(await undo($, e.force === true, 'claude')))

  on('tool.call', { tool: 'mcp__backlog__delete' }, async ($, e) => {
    const text = await mutate($, board => {
      const r = deleteItem(board, String(e.id ?? ''), e.cascade === true)
      return r.ok ? { board: r.value.board, out: `deleted ${r.value.removed.join(', ')}`, label: `delete ${r.value.removed.join(', ')}` } : { board, out: r.error }
    }, 'claude')
    return answer(text)
  })

  // ---------- slash commands ----------

  const HELP = `Backlog — data: ${storage === 'home' ? '~/.claude/backlog/<project>/board.json' : '<repo>/.backlog/ (git-ignored)'}
  /backlog                    open the board pane
  /idea <text>              have Claude plan an idea into an epic, stories and tasks
  /backlog list [view|text]   list items (views: ${VIEWS.join(', ')})
  /backlog add <title>        quick-add a task   (also: bug, story, epic, milestone)
  /backlog show <id>          show an item
  /backlog start|review|done|block|todo|later|cancel <id>
  /backlog rm <id> [--keep|--all]  delete an item (asks first if it has children)
  /backlog up|down|top|bottom <id>  reorder within its status
  /backlog undo               undo the last change (keeps 20)
  /backlog next               have Claude pick up the next item
  /backlog work <id>          have Claude work on an item
  /backlog plan <topic>        plan something together: Claude interviews you into a draft
  /backlog plan [D-n]          open a draft plan (lists them when several are open)
  /backlog accept|discard [D-n]  settle a draft
  /backlog allow [id] [plans|done] | revoke <id> [plans|done]  standing approvals for an epic/milestone
  /backlog branch <id> [--anyway]  start an item on its own git branch
  /backlog import-todos        propose the code's TODO/FIXME comments as tasks
  /backlog export md [path] [--open]  write the board as Markdown (ROADMAP.md)
  /backlog export github [--yes]      mirror open work to GitHub Issues (preview without --yes)
  /backlog band on|off         show or hide the band above the prompt
  /backlog web [stop]          open the board in the local web app
  /backlog where              print the data file path`

  on('command.run', { command: 'idea' }, async ($, e) => {
    const idea = e.args.trim()
    if (!idea) return { text: 'Usage: /idea <describe the idea>' }
    submitSoon($, ideaPrompt(idea))
    return { text: `Planning: ${idea}` }
  })

  on('command.run', { command: 'backlog' }, async ($, e) => {
    const [sub = '', ...rest] = e.args.trim().split(/\s+/)
    const arg = rest.join(' ').trim()
    const verb = sub.toLowerCase()
    const statusVerbs: Record<string, Status> = {
      start: 'in_progress', review: 'review', done: 'done', close: 'done', block: 'blocked',
      todo: 'todo', later: 'later', backlog: 'later', cancel: 'cancelled', reopen: 'todo',
    }

    if (!verb || verb === 'board' || verb === 'open') {
      await reload($)
      await $.ui.open({ id: PANE, title: 'Backlog', focus: true })
      return { text: 'Opened the Backlog board.' }
    }
    if (verb === 'help') return { text: HELP }
    if (verb === 'where') return { text: await locate($) }
    if ((MOVES as readonly string[]).includes(verb)) {
      if (!arg) return { text: `Usage: /backlog ${verb} <id>` }
      return { text: await moveFrom($, arg, verb as Move) }
    }
    if (verb === 'band') {
      const hide = arg === 'off' || arg === 'hide'
      await setBand($, hide)
      return { text: hide ? 'Backlog band hidden (/backlog band on to bring it back).' : 'Backlog band shown above the prompt.' }
    }
    if (verb === 'plan' || verb === 'drafts') {
      const board = await reload($)
      const open = openDrafts(board)
      if (arg && /^d-?\d+$/i.test(arg)) {
        const d = findDraft(board, arg)
        if (!d || d.status !== 'open') return { text: `No open draft "${arg}".` }
        await openDraft($, d.id)
        return { text: `Opened ${d.id} (${d.topic}).` }
      }
      if (arg) return { text: await startPlanning($, arg) }
      if (!open.length) return { text: 'No plan is waiting for review.' }
      await openDraft($, open.at(-1)!.id)
      return { text: open.length === 1 ? `Opened ${open[0]!.id} (${open[0]!.topic}).`
        : `Open drafts:\n${open.map(d => `  ${d.id} ${d.topic} · ${d.items.length} items`).join('\n')}\nShowing ${open.at(-1)!.id}; /backlog plan <id> for another.` }
    }
    if (verb === 'accept') {
      const [ref = '', flag = ''] = arg.split(/\s+/)
      const anyway = ref === '--anyway' || flag === '--anyway'
      return { text: await acceptProposal($, undefined, ref && ref !== '--anyway' ? ref : undefined, anyway) }
    }
    if (verb === 'allow') {
      const board = await reload($)
      if (!arg) {
        const what = (w: string) => (w === 'done' ? 'Claude may close its verified work' : "Claude's plans skip review")
        const list = (board.allow ?? []).map(a => `  ${a.scope} ${resolveId(board, a.scope)?.title ?? '(gone)'} · ${what(a.what)} · since ${a.at.slice(0, 10)}`)
        return { text: list.length ? `Standing approvals:\n${list.join('\n')}\n/backlog revoke <id> [plans|done] to take one back.` : 'No standing approvals: Claude\'s plans and finished work wait for your review. /backlog allow <epic or milestone> [plans|done].' }
      }
      const [ref = '', kind = 'plans'] = arg.split(/\s+/)
      const what = kind === 'done' ? 'done' as const : 'plans' as const
      const target = resolveId(board, ref)
      if (!target || (target.kind !== 'epic' && target.kind !== 'milestone')) return { text: `${ref} is not an epic or milestone.` }
      const text = await mutate($, (b, at) => ({
        board: { ...b, allow: [...(b.allow ?? []).filter(a => !(a.scope === target.id && a.what === what)), { scope: target.id, what, at }] },
        out: what === 'done'
          ? `Claude may close its own verified work under ${target.id} ${target.title}; you'll see what it closed in the band, and ${target.id} itself still waits for you. /backlog revoke ${target.id} done to take it back.`
          : `Plans Claude proposes under ${target.id} ${target.title} will be added without review. /backlog revoke ${target.id} to take it back.`,
        label: `allow ${what} under ${target.id}`,
      }))
      return { text }
    }
    if (verb === 'revoke') {
      const [ref = '', kind = ''] = arg.split(/\s+/)
      const scope = ref.toUpperCase()
      const hit = (a: { scope: string; what: string }) => a.scope.toUpperCase() === scope && (!kind || a.what === kind)
      const text = await mutate($, b => {
        const gone = (b.allow ?? []).filter(hit)
        return gone.length
          ? { board: { ...b, allow: (b.allow ?? []).filter(a => !hit(a)) }, out: `${gone.map(a => (a.what === 'done' ? `Claude's finished work under ${scope} goes to review again` : `Plans under ${scope} need your review again`)).join('; ')}.`, label: `revoke ${scope}${kind ? ` ${kind}` : ''}` }
          : { board: b, out: `There is no standing approval for "${arg}". /backlog allow lists them.` }
      })
      return { text }
    }
    if (verb === 'discard') return { text: await discardProposal($, arg || undefined) }
    if (verb === 'branch') {
      const [ref = '', flag = ''] = arg.split(/\s+/)
      if (!ref) return { text: 'Usage: /backlog branch <id> [--anyway]' }
      return { text: await startOnBranch($, ref, flag === '--anyway') }
    }
    if (verb === 'import-todos' || verb === 'todos') return { text: await importTodos($) }
    if (verb === 'export') {
      const [what = '', ...rest] = arg.split(/\s+/)
      if (what === 'md' || what === 'markdown') return { text: await exportMarkdown($, rest.join(' ')) }
      if (what === 'github' || what === 'issues') return { text: await exportGithub($, rest.includes('--yes')) }
      return { text: 'Usage: /backlog export md [path] [--open]  |  /backlog export github [--yes]' }
    }
    if (verb === 'web') return { text: await webCommand($, arg) }
    if (verb === 'undo') return { text: await undo($, arg === 'force') }
    if (verb === 'list' || verb === 'ls') {
      const board = await reload($)
      const items = VIEWS.includes(arg as View) ? viewItems(board, arg as View) : arg ? filterItems(board, { text: arg }) : viewItems(board, 'active')
      return { text: items.length ? items.map(i => line(board, i)).join('\n') : 'No matching items.' }
    }
    if (verb === 'summary') return { text: summary(await reload($)) }
    if (verb === 'show') {
      const board = await reload($)
      const item = resolveId(board, arg)
      return { text: item ? detail(board, item, { nowMs: await $.clock.now() }) : `No item "${arg}".` }
    }
    const kind = verb === 'add' ? 'task' : verb
    if ((KINDS as readonly string[]).includes(kind)) {
      if (!arg) return { text: `Usage: /backlog ${verb} <title>` }
      const text = await mutate($, (board, at) => {
        const r = createItems(board, [{ kind, title: arg }], at, 'user')
        return r.created[0] ? { board: r.board, out: `Created ${line(r.board, r.created[0])}`, label: `create ${r.created[0].id}` } : { board, out: r.errors.join('\n') }
      })
      return { text }
    }
    if (statusVerbs[verb]) {
      if (!arg) return { text: `Usage: /backlog ${verb} <id>` }
      return { text: await setStatus($, arg, statusVerbs[verb]!) }
    }
    if (verb === 'rm' || verb === 'delete') {
      const [ref = '', mode = ''] = arg.split(/\s+/)
      const item = resolveId(await reload($), ref)
      if (!item) return { text: ref ? `No item "${ref}".` : 'Usage: /backlog rm <id> [--keep | --all]' }
      const { children } = dependents((await read($, boardAtom))!, item)
      if (children.length && mode !== '--keep' && mode !== '--all') {
        const names = children.slice(0, 5).map(c => c.id).join(', ') + (children.length > 5 ? ', …' : '')
        return { text: `${item.id} has ${children.length} child item${children.length > 1 ? 's' : ''} (${names}). Nothing was deleted.\n  /backlog rm ${item.id} --keep   delete only ${item.id}; its children stay, detached\n  /backlog rm ${item.id} --all    delete ${item.id} and its children` }
      }
      return { text: await removeItem($, item.id, mode === '--all') + ' (/backlog undo restores it)' }
    }
    if (verb === 'next') {
      submitSoon($, nextPrompt)
      return { text: 'Asking Claude to pick up the next item.' }
    }
    if (verb === 'work') {
      const item = resolveId(await reload($), arg)
      if (!item) return { text: `No item "${arg}".` }
      submitSoon($, workPrompt(item))
      return { text: `Asking Claude to work on ${item.id}.` }
    }
    return { text: `Unknown subcommand "${sub}".\n\n${HELP}` }
  })

  // ---------- compact transcript rows for Backlog's own tools ----------

  for (const name of ['summary', 'list', 'show', 'create', 'propose', 'revise', 'update', 'delete', 'undo']) {
    on('ui.render', { component: 'ToolUse', props: { tool: `mcp__backlog__${name}` } }, async ($, e, next) => {
      // Errors and interruptions keep the engine's own row, which explains them.
      if (e.props.isErrored || e.props.isInterrupted) return next(e)
      const { Box, Text } = $.ui.resolve(e)
      const width = Math.max(30, e.viewport?.columns ?? 100)
      const text = toolLine(e.props.tool, e.props.input)
      return (
        <Box>
          <Text color="claude" bold>{'backlog '}</Text>
          <Text wrap="truncate-end">{text.length > width - 12 ? `${text.slice(0, width - 13)}…` : text}{e.props.isRunning ? ' …' : ''}</Text>
        </Box>
      )
    })
  }

  // ---------- proposed plan: the user reviews before anything is saved ----------

  on('ui.render', { component: 'Pane', requestId: PLAN }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const board = (await read($, boardAtom)) ?? emptyBoard('')
    const proposal = findDraft(board, (await read($, activeDraftAtom)) ?? undefined)
    const cols = Math.max(30, e.props.bodyColumns)
    const fit = (s: string, w: number) => (s.length > w ? `${s.slice(0, Math.max(1, w - 1))}…` : s)
    if (!proposal || proposal.status !== 'open') return <Text dimColor>No plan is waiting for review.</Text>
    const items = proposal.items as ItemInput[]
    const depths = planDepths(items)
    const kept = keptItems(items, proposal.include)
    const scope = proposalScope(board, items)
    const others = openDrafts(board).filter(d => d.id !== proposal.id)
    const openQs = openQuestions(proposal)
    const decided = [...(proposal.decisions ?? []).map(d => d.text), ...(proposal.questions ?? []).filter(q => q.answer).map(q => `${q.text} → ${q.answer}`)]
    const confirmingAccept = (await read($, planConfirmAtom)) === proposal.id
    const editing = await read($, planEditAtom)
    const target = items.find(i => i.ref === editing)
    // Editing a draft yourself: pick an item to reword it, change its criteria or points, or drop it; add new ones below.
    const editor = !target || e.surface === 'mobile' ? null : (() => {
      const { Input } = $.ui.resolve(e)
      const ref = target.ref!
      const set = (u: Partial<ItemInput>) => void editDraft($, proposal.id, { update: [{ ref, ...u }] })
      return (
        <Box key="plan-editor" flexDirection="column" borderStyle="round" paddingX={1} marginTop={1}>
          <Text bold>{fit(`Editing ${target.kind} · ${target.title}`, cols - 6)}</Text>
          <Input key="plan-edit-title" label="Title" value={target.title} submitLabel="Save" onSubmit={v => { if (v.trim()) set({ title: v.trim() }) }} />
          <Input key="plan-edit-description" label="Why / approach" value={target.description ?? ''} submitLabel="Save" onSubmit={v => set({ description: v })} />
          <Input key="plan-edit-criteria" label="Criteria (separate with |)" value={(target.acceptance ?? []).join(' | ')} submitLabel="Save"
            onSubmit={v => set({ acceptance: criteriaFrom(v) })} />
          <Input key="plan-edit-points" label="Points" value={target.points === undefined ? '' : String(target.points)} submitLabel="Save"
            onSubmit={v => { const n = Number(v); if (v.trim() && Number.isFinite(n)) set({ points: n }) }} />
          <Box columnGap={1}>
            <Button key="plan-edit-drop" label="Drop this item" onPress={() => void editDraft($, proposal.id, { remove: [ref] }).then(() => update($, planEditAtom, () => null))} />
            <Button key="plan-edit-done" label="Done" hotkey="e" onPress={() => void update($, planEditAtom, () => null)} />
          </Box>
        </Box>
      )
    })()
    const adder = e.surface === 'mobile' ? null : (() => {
      const { Input, Select } = $.ui.resolve(e)
      const parents = items.filter(i => i.kind === 'epic' || i.kind === 'story')
      const parentRef = parents.find(p => p.ref === editing)?.ref ?? parents[0]?.ref
      return (
        <Box key="plan-adder" flexDirection="column" marginTop={1}>
          {parents.length > 1 && (
            <Select key="plan-add-parent" label="Add under" value={parentRef ?? ''}
              options={parents.map(p => ({ value: p.ref!, label: fit(`${p.kind} · ${p.title}`, 50) }))}
              onSelect={v => void update($, planEditAtom, () => v)} />
          )}
          <Input key="plan-add" label={parentRef ? `Add a story under ${fit(parents.find(p => p.ref === parentRef)?.title ?? '', 30)}` : 'Add an item'}
            placeholder="title, Enter to add" submitLabel="Add"
            onSubmit={v => {
              if (!v.trim()) return
              const parent = parents.find(p => p.ref === parentRef)
              const kind = parent?.kind === 'story' ? 'task' : parent ? 'story' : 'epic'
              void editDraft($, proposal.id, { add: [{ kind, title: v.trim(), ...(parent ? { parent: parent.ref } : {}) }] })
            }} />
        </Box>
      )
    })()
    return (
      <Box flexDirection="column">
        <Text bold>{fit(`${proposal.id} · ${proposal.topic}`, cols)}</Text>
        <Text>{items.length ? `Claude proposes ${items.length} item${items.length === 1 ? '' : 's'}. Untick what you don't want, then accept.` : 'Empty so far: Claude is interviewing you in the chat and will fill this in.'}</Text>
        {openQs.length > 0 && (
          <Box key="plan-questions" flexDirection="column" marginTop={1}>
            <Text bold>{`Open questions (${openQs.length})`}</Text>
            {openQs.map(q => <Text wrap="truncate-end">{fit(`? ${q.text}`, cols - 2)}</Text>)}
          </Box>
        )}
        {decided.length > 0 && (
          <Box key="plan-decisions" flexDirection="column" marginTop={1}>
            <Text bold>{`Decided (${decided.length})`}</Text>
            {decided.slice(-6).map(t => <Text dimColor wrap="truncate-end">{fit(`✓ ${t}`, cols - 2)}</Text>)}
          </Box>
        )}
        <Text dimColor>Unticking an item also drops what's under it. Nothing is on the board yet.</Text>
        <Box flexDirection="column" marginTop={1}>
          {items.map((it, n) => {
            const keep = proposal.include[n] && kept.includes(it)
            const extra = [it.points !== undefined ? `${it.points}pt` : '', it.acceptance?.length ? `${it.acceptance.length} criteria` : ''].filter(Boolean).join(', ')
            const label = `${keep ? '[x]' : '[ ]'} ${'  '.repeat(depths[n] ?? 0)}${it.kind} · ${it.title}${extra ? ` (${extra})` : ''}${it.parent && !items.some(o => o.ref === it.parent) ? ` → ${it.parent}` : ''}`
            const ticked = label.slice(0, 3)
            return (
              <Box key={`plan-row-${n}`}>
                <Button key={`plan-${n}`} plain dimColor={!keep} label={ticked} onPress={() => void toggleProposed($, proposal.id, n)} />
                <Button key={`plan-edit-${n}`} plain dimColor={!keep} label={fit(label.slice(3), cols - 6) + (it.ref === editing ? '  ✎' : '')}
                  onPress={() => void update($, planEditAtom, cur => (cur === it.ref ? null : it.ref ?? null))} />
              </Box>
            )
          })}
        </Box>
        {editor}
        {adder}
        <Box marginTop={1} columnGap={1}>
          {confirmingAccept ? (
            <Box key="plan-confirm" columnGap={1} flexWrap="wrap">
              <Text>{`${openQs.length} question${openQs.length === 1 ? ' is' : 's are'} still open.`}</Text>
              <Button key="plan-accept-anyway" label="Accept anyway" hotkey="a" variant="primary"
                onPress={() => void acceptProposal($, undefined, proposal.id, true).then(t => $.ui.toast(t))} />
              <Button key="plan-keep" label="Keep planning" hotkey="k" onPress={() => void update($, planConfirmAtom, () => null)} />
            </Box>
          ) : (
            <Button key="plan-accept" label={`Accept ${kept.length} item${kept.length === 1 ? '' : 's'}`} hotkey="a" variant="primary"
              onPress={() => void (openQs.length
                ? update($, planConfirmAtom, () => proposal.id)
                : acceptProposal($, undefined, proposal.id).then(t => $.ui.toast(t)))} />
          )}
          {scope && !confirmingAccept && openQs.length === 0 && (
            <Button key="plan-accept-allow" label={`Accept, and allow plans under ${scope} from now on`} hotkey="l"
              onPress={() => void acceptProposal($, scope, proposal.id).then(t => $.ui.toast(t))} />
          )}
          {scope && !confirmingAccept && openQs.length === 0 && (
            <Button key="plan-accept-trust" label={`…and let Claude close its verified work there`} hotkey="f"
              onPress={() => void acceptProposal($, scope, proposal.id, false, true).then(t => $.ui.toast(t))} />
          )}
          <Button key="plan-discard" label="Discard" hotkey="d" onPress={() => void discardProposal($, proposal.id).then(t => $.ui.toast(t))} />
        </Box>
        {others.length > 0 && (
          <Box key="plan-others" marginTop={1} columnGap={1} flexWrap="wrap">
            <Text dimColor>Other drafts:</Text>
            {others.map(d => <Button key={`plan-open-${d.id}`} plain label={fit(`${d.id} ${d.topic}`, 40)} onPress={() => void openDraft($, d.id)} />)}
          </Box>
        )}
        <Box marginTop={1}><Text dimColor>[ ] ticks · press a title to edit it · a accept · l accept and allow · d discard · esc keeps it for later (/backlog plan)</Text></Box>
      </Box>
    )
  })

  // ---------- band above the prompt: what Claude is on, and what waits for the user ----------

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, bandHiddenAtom))) return next(e)
    const board = await read($, boardAtom)
    if (!board) return next(e)
    const work = (s: Status) => sortItems(board.items.filter(i => i.status === s && i.kind !== 'epic' && i.kind !== 'milestone'))
    const doing = work('in_progress')
    const review = work('review')
    const ready = closable(board)
    const upNext = work('todo')[0]
    if (!doing.length && !review.length && !ready.length && !upNext && !openDrafts(board).length) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const cols = Math.max(30, e.props.bodyColumns)
    const fit = (s: string, w: number) => (s.length > w ? `${s.slice(0, Math.max(1, w - 1))}…` : s)
    // Buttons draw as "[ label ]": their width is fixed, so the text gives way and the buttons never move.
    const buttonsWidth = (labels: string[]) => labels.reduce((w, l) => w + l.length + 5, 0)

    // Line 1, Claude: what it is on, with a tick per acceptance criterion.
    const current = doing[0]
    const ticks = current?.acceptance?.length ? ` ${current.acceptance.map((_, n) => (current.met?.[n] ? '✓' : '·')).join('')}` : ''
    const more = doing.length > 1 ? ` +${doing.length - 1}` : ''
    const line1 = current ? `◐ Claude: ${current.id} ${current.title}` : '○ Claude: nothing in progress'
    const right1 = ['Board']
    const room1 = cols - buttonsWidth(right1) - 1
    const text1 = fit(line1, Math.max(8, room1 - ticks.length - more.length)) + ticks + more

    // Line 2, you: what comes next, and what waits for you (always in this order: review, close).
    const nowMs = await $.clock.now()
    const autoClosed = sortItems(board.items.filter(i => i.closedUnder && i.status === 'done' && i.closedAt && nowMs - Date.parse(i.closedAt) < 86_400_000))
    const right2 = [...(review.length ? [`${review.length} to review`] : []), ...(autoClosed.length ? [`${autoClosed.length} closed by Claude`] : []), ...(ready.length ? [`${ready.length} to close`] : [])]
    const draft = [...openDrafts(board)].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0]
    if (draft) right2.unshift('Review draft')
    const line2 = draft
      ? `  Planning: ${draft.topic} · ${draft.items.length} item${draft.items.length === 1 ? '' : 's'}${openQuestions(draft).length ? ` · ${openQuestions(draft).length} open` : ''}`
      : upNext ? `  Next up: ${upNext.id} ${upNext.title}` : '  Nothing queued'
    const text2 = fit(line2, Math.max(8, cols - buttonsWidth(right2) - 1))
    // The band is shared: draw Backlog's lines, then whatever the mods beneath draw.
    const below = await next(e)

    return (
      <Box flexDirection="column">
        <Box key="band-line1" justifyContent="space-between">
          {current
            ? <Button key="band-current" plain label={text1} onPress={() => void openBoard($, 'active', current.id)} />
            : <Text dimColor>{text1}</Text>}
          <Box columnGap={1}>
            <Button key="band-open" label="Board" onPress={() => void openBoard($, current ? 'active' : undefined, current?.id)} />
          </Box>
        </Box>
        <Box key="band-line2" justifyContent="space-between">
          {draft
            ? <Button key="band-draft" plain label={text2} onPress={() => void openDraft($, draft.id)} />
            : upNext
            ? <Button key="band-next" plain dimColor label={text2} onPress={() => void openBoard($, 'active', upNext.id)} />
            : <Text dimColor>{text2}</Text>}
          <Box columnGap={1}>
            {draft && <Button key="band-review-draft" label="Review draft" onPress={() => void openDraft($, draft.id)} />}
            {review.length > 0 && (
              <Button key="band-review" label={`${review.length} to review`} variant="primary"
                onPress={() => void openBoard($, 'active', review[0]!.id)} />
            )}
            {autoClosed.length > 0 && (
              <Button key="band-auto" label={`${autoClosed.length} closed by Claude`}
                onPress={() => void openBoard($, 'done', autoClosed[0]!.id)} />
            )}
            {ready.length > 0 && (
              <Button key="band-ready" label={`${ready.length} to close`}
                onPress={() => void openBoard($, ready[0]!.kind === 'milestone' ? 'milestones' : 'epics', ready[0]!.id)} />
            )}
          </Box>
        </Box>
        {below}
      </Box>
    )
  })

  // ---------- board pane ----------

  // Which row holds the keyboard, so the pane can draw a cursor that's distinct from the selection.
  on('ui.focus', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    const result = await next(e)
    if ('deny' in result && result.deny) return result
    await update($, focusedAtom, () => e.element ?? null)
    // Focus and selection are one cursor: landing on a row (arrows, tab or j/k) selects it.
    const row = e.element?.match(/^(?:item|child)-(.+)$/)
    if (row) await selectItem($, row[1]!, false)
    return result
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const board = (await read($, boardAtom)) ?? emptyBoard('')
    const saved = await read($, viewAtom)
    const view: View = VIEWS.includes(saved) ? saved : 'active'
    const selected = resolveId(board, await read($, selectedAtom))
    const lastChange = await read($, lastChangeAtom)
    const confirming = selected !== undefined && (await read($, confirmAtom)) === selected.id
    const editing = selected !== undefined && e.surface !== 'mobile' && (await read($, editingAtom))
    const cols = Math.max(20, e.props.bodyColumns)
    const fit = (s: string, w = cols) => (s.length > w ? `${s.slice(0, w - 1)}…` : s)
    const focusKey = e.props.isFocused ? await read($, focusedAtom) : null
    // One cursor: ▌ (accent) marks the current item; the engine's inverse shows where the keyboard is.
    const row = (key: string, id: string, label: string, width: number, dim = false) => (
      <Box key={`row-${key}`}>
        <Text color="claude" bold>{id === selected?.id ? '▌ ' : '  '}</Text>
        <Button key={key} plain dimColor={dim && id !== selected?.id} label={fit(label, Math.max(4, width - 2))}
          onPress={() => void (id === selected?.id ? focusCard() : selectItem($, id))} />
      </Box>
    )
    // The pane's own height, not the terminal's: the list gets what the rest leaves.
    const rows = e.props.scroll?.bodyRows || e.viewport?.rows || 30
    const query = e.surface === 'mobile' ? '' : (await read($, queryAtom)).trim()
    const inView = viewItems(board, view)
    const items = query ? inView.filter(i => matchesQuery(i, query)) : inView
    const elsewhere = query && items.length === 0 && view !== 'all'
      ? viewItems(board, 'all').filter(i => matchesQuery(i, query)).length : 0
    const wideLayout = cols >= 120
    const cardRows = !selected ? 0 : editing ? 2 + 2 + 9 + 2 : (() => {
      const detailRows = Math.min(12, detail(board, selected, { acceptance: false, history: false, notes: !wideLayout, code: false }).split('\n').length)
      const acRows = selected.acceptance?.length ? 2 + selected.acceptance.length : 0
      const c = codeOf(board, selected)
      const shown = Math.min(c.commits.length, wideLayout ? 5 : 3)
      const codeRows = c.commits.length || c.branches.length ? 2 + (c.branches.length ? 1 : 0) + shown + (c.commits.length > shown ? 1 : 0) : 0
      const sideRows = wideLayout ? codeRows + 1 + Math.max(1, Math.min(3, selected.comments.length)) + ((selected.activity?.length ?? 0) ? 2 + Math.min(6, selected.activity!.length) : 0) : 0
      const body = wideLayout ? Math.max(detailRows + acRows, sideRows) : detailRows + acRows + codeRows
      return 2 + body + 1 + (wideLayout ? 1 : 2) + (confirming ? 3 : 0) + 1
    })()
    const chromeRows = (e.props.isFocused ? 0 : 1) + 2 + 2 + 2 + 1 + (e.surface === 'mobile' || editing || board.items.length === 0 ? 0 : 3) + (lastChange && !editing ? 2 : 0) + (selected ? 0 : 1) + 2 + 1
    const room = Math.max(3, rows - chromeRows - cardRows)
    const open = board.items.filter(i => !isClosed(i.status) && i.kind !== 'epic' && i.kind !== 'milestone')
    const doing = open.filter(i => i.status === 'in_progress').length
    const done = board.items.filter(i => i.status === 'done' && i.kind !== 'epic' && i.kind !== 'milestone').length
    const project = board.project.split('/').filter(Boolean).at(-1) ?? 'project'

    const actions = selected ? actionsFor(selected, readyToClose(board, selected), closeBlockOf(board, selected)) : []
    const group = selected ? siblings(board, selected) : []
    const place = selected ? group.findIndex(i => i.id === selected.id) : -1
    const canUp = place > 0
    const canDown = place >= 0 && place < group.length - 1
    const canWork = selected !== undefined && !isClosed(selected.status) && selected.kind !== 'milestone' && !readyToClose(board, selected)

    const next = nextUp(board)
    // The active view reads as a board: a heading per status, so the row drops its [status] tag.
    const wide = cols >= 120
    const kanban = wide && view === 'active' && items.length > 0
    const cardSide = wide && !editing
    const cardLeft = Math.floor((cols - 4) * 0.55)
    const nowMs = await $.clock.now()
    const code = selected ? codeOf(board, selected) : { branches: [], commits: [] }
    const codeWidth = cardSide ? cols - cardLeft - 8 : cols - 6
    const codeView = selected && (code.commits.length || code.branches.length) ? (
      <Box key="code" flexDirection="column" marginTop={cardSide ? 0 : 1} marginBottom={cardSide ? 1 : 0}>
        <Text bold>{fit(`Code · ${code.commits.length} commit${code.commits.length === 1 ? '' : 's'}`, codeWidth)}</Text>
        {code.branches.length > 0 && <Text>{fit(`branch ${code.branches.join(', ')}`, codeWidth)}</Text>}
        {code.commits.slice(0, cardSide ? 5 : 3).map(c => (
          <Text wrap="truncate-end">{fit(`${c.hash.slice(0, 7)} ${c.subject} · ${c.author} · ${ago(c.at, nowMs)}`, codeWidth)}</Text>
        ))}
        {code.commits.length > (cardSide ? 5 : 3) && <Text dimColor>{`+${code.commits.length - (cardSide ? 5 : 3)} more (/backlog show ${selected.id})`}</Text>}
      </Box>
    ) : null
    const grouped = view === 'active'
    type Row = { heading?: { status: Status; count: number }; first?: boolean; item?: Item; depth?: number }
    const listRows: Row[] = grouped
      ? groupByStatus(items).flatMap((g, n) => [
        { heading: { status: g.status, count: g.items.length }, first: n === 0 },
        ...g.items.map(item => ({ item })),
      ])
      : items.map(item => ({ item }))
    const expanded = resolveId(board, await read($, expandedAtom))
    let showsChildren = false
    if (expanded && listRows.some(r => r.item?.id === expanded.id)) {
      // Children show under their parent only, not a second time at top level.
      const children = childRows(board, expanded)
      const ids = new Set(children.map(c => c.item.id))
      const kept = listRows.filter(r => !r.item || !ids.has(r.item.id))
      kept.splice(kept.findIndex(r => r.item?.id === expanded.id) + 1, 0, ...children)
      listRows.splice(0, listRows.length, ...kept)
      showsChildren = true
    }
    // Keep the keyboard's row in view: slide the window down when focus moves past it.
    const focusAt = focusKey ? listRows.findIndex(r => r.item && (`item-${r.item.id}` === focusKey || `child-${r.item.id}` === focusKey)) : -1
    const start = focusAt >= room ? focusAt - room + 1 : 0
    const rowsShown = listRows.slice(start, start + room)
    const hidden = items.length - rowsShown.filter(r => r.item && !r.depth).length - listRows.slice(0, start).filter(r => r.item && !r.depth).length
    // j/k walk the items in the order they're drawn (kanban: column by column), selecting as they go.
    const order: string[] = kanban
      ? (['todo', 'in_progress', 'review', 'blocked'] as Status[]).flatMap(st => items.filter(i => i.status === st).slice(0, room).map(i => i.id))
      : listRows.filter(r => r.item).map(r => r.item!.id)
    const step = async (by: number) => {
      const at = selected ? order.indexOf(selected.id) : -1
      const target = order[at < 0 ? (by > 0 ? 0 : order.length - 1) : Math.max(0, Math.min(order.length - 1, at + by))]
      if (!target || target === selected?.id) return
      // Move the focus; the ui.focus hook selects the row, so arrows and j/k are the same cursor.
      const isChild = listRows.some(r => r.depth && r.item?.id === target)
      await selectItem($, target, false)
      await $.ui.focus({ requestId: PANE, key: `${isChild ? 'child' : 'item'}-${target}` }).catch(() => undefined)
    }
    // Enter on the selected row steps into its card, onto the main action.
    const focusCard = () => $.ui.focus({ requestId: PANE, key: actions[0] ? `set-${actions[0].status}` : e.surface === 'mobile' ? 'deselect' : 'edit-toggle' }).catch(() => undefined)
    const legend = fit([
      ...(e.props.isFocused ? [] : ['keys off']),
      ...(confirming
        ? ['y delete', 'n cancel', 'u undo afterwards']
        : editing
        ? ['enter saves a field', 'e done editing', 'x close']
        : selected
        ? [...actions.filter(a => !a.blocked).map(a => `${a.hotkey} ${a.short}`), ...(canWork ? ['w claude'] : []), 'e edit', 'x close']
        : [`1-${VIEWS.length} views`, 'tab/↑↓ move', 'enter open', ...(lastChange ? ['u undo'] : []), 'esc prompt']),
    ].join(' · '))

    const editForm = !editing || !selected ? null : (() => {
      const { Input, Select } = $.ui.resolve(e)
      const save = (patch: ItemPatch) => void mutate($, (b, at) => {
        const r = updateItem(b, selected.id, patch, at, 'user')
        return { board: r.ok ? r.value.board : b, out: null, label: `edit ${selected.id}` }
      })
      const parents = selected.kind === 'milestone' || selected.kind === 'epic' ? [] : board.items.filter(i =>
        !isClosed(i.status) && i.id !== selected.id && (i.kind === 'epic' || (i.kind === 'story' && selected.kind !== 'story')))
      const milestones = selected.kind === 'milestone' ? [] : board.items.filter(i => i.kind === 'milestone' && !isClosed(i.status))
      const none = { value: 'none', label: '(none)' }
      return (
        <Box key="edit" flexDirection="column" marginTop={1}>
          <Input key="edit-title" label="Title" value={selected.title} submitLabel="Save"
            onSubmit={title => save({ title })} />
          <Input key="edit-description" label="Description" value={selected.description ?? ''} placeholder="markdown" submitLabel="Save"
            onSubmit={description => save({ description })} />
          <Select key="edit-priority" label="Priority" value={selected.priority}
            options={PRIORITIES.map(p => ({ value: p, label: p }))}
            onSelect={priority => save({ priority })} />
          {parents.length > 0 && (
            <Select key="edit-parent" label={selected.kind === 'story' ? 'Epic' : 'Epic or story'} value={selected.parent ?? 'none'}
              options={[none, ...parents.map(i => ({ value: i.id, label: fit(`${i.id} ${i.title}`, 60) }))]}
              onSelect={parent => save({ parent })} />
          )}
          {milestones.length > 0 && (
            <Select key="edit-milestone" label="Milestone" value={selected.milestone ?? 'none'}
              options={[none, ...milestones.map(i => ({ value: i.id, label: fit(`${i.id} ${i.title}`, 60) }))]}
              onSelect={milestone => save({ milestone })} />
          )}
        </Box>
      )
    })()

    const search = e.surface === 'mobile' || board.items.length === 0 ? null : (() => {
      const { Input } = $.ui.resolve(e)
      return (
        <Box key="search-row" marginTop={1}>
          <Input key="search" label="Find" value={query} placeholder="words, #label or id; filters as you type" submitLabel="Find"
            onInput={text => void update($, queryAtom, () => text)}
            onSubmit={text => void update($, queryAtom, () => text)} />
          {query !== '' && (
            <Button key="search-clear" label={`Clear (${items.length} match${items.length === 1 ? '' : 'es'})`}
              onPress={() => void update($, queryAtom, () => '')} />
          )}
        </Box>
      )
    })()

    const forms = e.surface === 'mobile' ? null : (() => {
      const { Input } = $.ui.resolve(e)
      return (
        <Box flexDirection="column" marginTop={1}>
          <Input key="quick-add" label="Add task" placeholder="title, Enter to add" submitLabel="Add"
            onSubmit={title => {
              if (!title.trim()) return
              void mutate($, (b, at) => {
                const r = createItems(b, [{ kind: 'task', title }], at, 'user')
                return { board: r.created.length ? r.board : b, out: null, label: `create ${r.created[0]?.id ?? ''}` }
              })
            }} />
          <Input key="idea" label="Plan idea" placeholder="describe an idea; Claude breaks it into an epic and stories" submitLabel="Plan"
            onSubmit={idea => {
              if (idea.trim()) submitSoon($, ideaPrompt(idea.trim()))
            }} />
        </Box>
      )
    })()

    return (
      <Box flexDirection="column">
        <Text bold>{fit(`Backlog · ${project}`)}</Text>
        <Text dimColor>{fit(`${doing} in progress · ${open.length} open · ${done} done`)}</Text>
        <Box flexWrap="wrap" marginTop={1}>
          {VIEWS.map((v, n) => (
            <Button key={`view-${v}`} label={v} hotkey={String(n + 1)} variant={v === view ? 'primary' : 'secondary'}
              onPress={() => void update($, viewAtom, () => v)} />
          ))}
        </Box>
        {search}
        <Box flexDirection="column" marginTop={1}>
          {board.items.length === 0 && (
            <Box key="welcome" flexDirection="column">
              <Text bold>Welcome to Backlog: a project tracker that Claude reads and updates.</Text>
              <Text dimColor>Milestone › Epic › Story, Task or Bug. Work moves: to do → in progress → review → done.</Text>
              <Text>{e.surface === 'mobile'
                ? 'Start with /backlog add <title>, /idea <text>, or just ask Claude to plan something.'
                : 'Start: add a task below, describe an idea for Claude to plan, or just ask Claude in chat.'}</Text>
            </Box>
          )}
          {board.items.length > 0 && items.length === 0 && (
            <Text dimColor>{query
              ? `No matches for "${query}" here.${elsewhere ? ` ${elsewhere} in all: press ${VIEWS.indexOf('all') + 1}.` : ''}`
              : 'Nothing in this view.'}</Text>
          )}
          {kanban && (() => {
            // Wide pane: the active view as side-by-side columns, like the web board.
            const columns: Status[] = ['todo', 'in_progress', 'review', 'blocked']
            const colWidth = Math.floor((cols - (columns.length - 1) * 2) / columns.length)
            return (
              <Box key="kanban" columnGap={2}>
                {columns.map(status => {
                  const list = items.filter(i => i.status === status)
                  return (
                    <Box key={`col-${status}`} flexDirection="column" width={colWidth}>
                      <Text bold>{fit(`${STATUS_LABEL[status]} (${list.length})`, colWidth)}</Text>
                      {list.length === 0 && <Text dimColor>—</Text>}
                      {list.slice(0, room).map(i => {
                        const a = acceptanceProgress(i)
                        const tag = a ? ` ✓${a.met}/${a.total}` : ''
                        return row(`item-${i.id}`, i.id, fit(`${STATUS_GLYPH[i.status]} ${i.id} ${i.title}`, colWidth - tag.length - 3) + tag, colWidth)
                      })}
                      {list.length > room && <Text dimColor>{`+${list.length - room} more`}</Text>}
                    </Box>
                  )
                })}
              </Box>
            )
          })()}
          {!kanban && rowsShown.map(r => {
            if (r.heading) return (
              <Box key={`group-${r.heading.status}`} marginTop={r.first ? 0 : 1}>
                <Text bold>{`${STATUS_LABEL[r.heading.status]} (${r.heading.count})`}</Text>
              </Box>
            )
            const i = r.item!
            const p = i.kind === 'epic' || i.kind === 'milestone' ? progress(board, i) : null
            if (r.depth) {
              const indent = r.depth === 1 ? ' └ ' : '     └ '
              return row(`child-${i.id}`, i.id, `${indent}${line(board, i)}`, cols - 2, isClosed(i.status))
            }
            const open = expanded?.id === i.id ? '▾ ' : membersOf(board, i).length ? '▸ ' : ''
            const text = `${open}${line(board, i, { status: !grouped })}`
            const label = p ? `${text} ${bar(p.percent, 8)}` : text
            return row(`item-${i.id}`, i.id, label, cols - 2, isClosed(i.status))
          })}
          {!kanban && hidden > 0 && <Text dimColor>{`…and ${hidden} more (/backlog list ${view})`}</Text>}
        </Box>
        {selected && (
          <Box flexDirection="column" borderStyle="round" paddingX={1} marginTop={1}>
            <Box key="card-body" columnGap={3}>
              <Box flexDirection="column" width={cardSide ? cardLeft : undefined} flexGrow={cardSide ? 0 : 1}>
                {detail(board, selected, { acceptance: false, members: !showsChildren, history: false, notes: !cardSide, code: false }).split('\n').slice(0, editing ? 2 : 12).map(l => <Text wrap="truncate-end">{l || ' '}</Text>)}
                {!editing && selected.acceptance?.length ? (
                  <Box key="acceptance" flexDirection="column" marginTop={1}>
                    <Text bold>{`Acceptance criteria (${acceptanceProgress(selected)!.met}/${selected.acceptance.length} met)`}</Text>
                    {selected.acceptance.map((c, n) => (
                      <Button key={`ac-${n + 1}`} plain label={fit(`${selected.met?.[n] ? '[x]' : '[ ]'} ${c}`, (cardSide ? cardLeft : cols) - 6)}
                        onPress={() => void toggleCriterion($, selected.id, n + 1, !selected.met?.[n])} />
                    ))}
                  </Box>
                ) : null}
              </Box>
              {cardSide && (
                // Wide pane: what was said and done on the item, beside it rather than below.
                <Box key="card-side" flexDirection="column" flexGrow={1}>
                  {codeView}
                  <Text bold>Notes</Text>
                  {selected.comments.length === 0 && <Text dimColor>No notes yet.</Text>}
                  {selected.comments.slice(-3).map(c => (
                    <Text>{`${c.at.slice(5, 16).replace('T', ' ')} ${c.author}: ${c.text}`}</Text>
                  ))}
                  {(selected.activity?.length ?? 0) > 0 && <Box marginTop={1}><Text bold>History</Text></Box>}
                  {(selected.activity ?? []).slice(-6).reverse().map(c => (
                    <Text dimColor wrap="truncate-end">{`${c.at.slice(5, 16).replace('T', ' ')} ${c.author}: ${c.text}`}</Text>
                  ))}
                </Box>
              )}
            </Box>
            {!cardSide && !editing && codeView}
            <Box flexWrap="wrap" marginTop={1}>
              {!editing && actions.map(a => (a.blocked
                // A move that isn't earned yet has no button to press, only why.
                ? <Text key={`set-${a.status}`} dimColor>{`[ ${a.label} ] needs: ${a.blocked}  `}</Text>
                : <Button key={`set-${a.status}`} label={a.label} hotkey={a.hotkey} variant={a.primary ? 'primary' : 'secondary'}
                  onPress={() => void statusFromPane($, selected.id, a.status)} />
              ))}
              {!editing && (selected.status === 'todo' || selected.status === 'later') && selected.kind !== 'epic' && selected.kind !== 'milestone' && (
                <Button key="branch" label="Start on a new branch" onPress={() => void branchFromPane($, selected.id)} />
              )}
              {!editing && canUp && <Button key="move-up" label="↑ Move up" onPress={() => void moveFrom($, selected.id, 'up')} />}
              {!editing && canDown && <Button key="move-down" label="↓ Move down" onPress={() => void moveFrom($, selected.id, 'down')} />}
              {!editing && canWork && <Button key="work" label="Ask Claude to work on it" hotkey="w"
                onPress={() => submitSoon($, workPrompt(selected))} />}
              {e.surface !== 'mobile' && (
                <Button key="edit-toggle" label={editing ? 'Done editing' : 'Edit'} hotkey="e"
                  onPress={() => void update($, editingAtom, cur => !cur)} />
              )}
              {!editing && !confirming && (
                <Button key="delete" label="Delete" onPress={() => void update($, confirmAtom, () => selected.id)} />
              )}
              <Button key="deselect" label="Close" hotkey="x" onPress={() => void closeItem($)} />
            </Box>
            {confirming && (() => {
              const { children, targeted } = dependents(board, selected)
              const also = [
                children.length ? `${children.length} child item${children.length > 1 ? 's' : ''}` : '',
                targeted.length ? `${targeted.length} item${targeted.length > 1 ? 's' : ''} targeting it (they stay)` : '',
              ].filter(Boolean).join(', ')
              return (
                <Box key="confirm" flexDirection="column" marginTop={1}>
                  <Text color="warning">{fit(`Delete ${selected.id}?${also ? ` It has ${also}.` : ''}`, cols - 4)}</Text>
                  <Box flexWrap="wrap">
                    <Button key="confirm-delete" label={children.length ? `Delete only ${selected.id}` : 'Delete'} hotkey="y"
                      onPress={() => void deleteFromPane($, selected.id, false)} />
                    {children.length > 0 && (
                      <Button key="confirm-cascade" label={`Delete with ${children.length} children`}
                        onPress={() => void deleteFromPane($, selected.id, true)} />
                    )}
                    <Button key="confirm-cancel" label="Cancel" hotkey="n" variant="primary"
                      onPress={() => void update($, confirmAtom, () => null)} />
                  </Box>
                </Box>
              )
            })()}
            {editForm}
          </Box>
        )}
        {!editing && forms}
        {lastChange && !editing && (
          <Box key="undo-row" marginTop={1}>
            <Button key="undo" label={fit(`Undo: ${lastChange}`, cols - 4)} hotkey="u" onPress={() => void undoFromPane($)} />
          </Box>
        )}
        {next && !selected && <Text dimColor>{fit(`Next up: ${next.id} ${next.title}`)}</Text>}
        <Box key="legend-row" marginTop={1} columnGap={1}>
          {!editing && order.length > 0 && <Button key="nav-prev" plain dimColor label="prev" hotkey="k" onPress={() => void step(-1)} />}
          {!editing && order.length > 0 && <Button key="nav-next" plain dimColor label="next" hotkey="j" onPress={() => void step(1)} />}
          <Box key="legend"><Text dimColor wrap="truncate-end">{legend}</Text></Box>
        </Box>
      </Box>
    )
  })
}

