// Pure board logic: no `$`, so tests and every hook share it.
import type { Board, CodeRecord, Comment, CommitRef, Draft, Item, Kind, Priority, SourceRef, Status, View } from '../types'

export const KINDS: readonly Kind[] = ['milestone', 'epic', 'story', 'task', 'bug']
export const STATUSES: readonly Status[] = [
  'later', 'todo', 'in_progress', 'review', 'blocked', 'done', 'cancelled',
]
export const PRIORITIES: readonly Priority[] = ['low', 'medium', 'high', 'critical']
export const VIEWS: readonly View[] = ['active', 'later', 'epics', 'milestones', 'done', 'all']

const PREFIX: Record<Kind, string> = { milestone: 'M', epic: 'E', story: 'S', task: 'T', bug: 'B' }
const PRIORITY_RANK: Record<Priority, number> = { critical: 0, high: 1, medium: 2, low: 3 }
const STATUS_RANK: Record<Status, number> = {
  in_progress: 0, review: 1, blocked: 2, todo: 3, later: 4, done: 5, cancelled: 6,
}
const CLOSED: readonly Status[] = ['done', 'cancelled']
export const ACTIVITY_LIMIT = 30
export const LOG_LIMIT = 50

/** Older and casual names for statuses; `backlog` was the original name of `later`. */
const STATUS_ALIASES: Record<string, Status> = {
  backlog: 'later', icebox: 'later', someday: 'later', wip: 'in_progress', doing: 'in_progress',
  started: 'in_progress', open: 'todo', closed: 'done', complete: 'done', completed: 'done',
}

export function normalizeStatus(value: string): string {
  const v = value.trim().toLowerCase().replace(/[\s-]+/g, '_')
  return STATUS_ALIASES[v] ?? v
}

/** Brings a board saved by an older version up to date. */
export function migrate(board: Board): Board {
  const stale = (i: Item) => !STATUSES.includes(i.status) || (i.status === 'done' && i.acceptance?.length && !i.met)
  // Commit notes from before code records existed move into them.
  if (board.items.some(i => !i.code && i.comments.some(c => /^commit [0-9a-f]{7,}: /.test(c.text)))) {
    board = { ...board, items: board.items.map(i => {
      const notes = i.comments.filter(c => /^commit [0-9a-f]{7,}: /.test(c.text))
      if (i.code || !notes.length) return i
      const commits = notes.map(c => {
        const m = c.text.match(/^commit ([0-9a-f]{7,}): (.*)$/s)!
        return { hash: m[1]!, subject: m[2]!.trim(), author: c.author === 'claude' ? 'Claude' : 'user', at: c.at }
      }).reverse()
      return { ...i, code: { branches: [], commits } }
    }) }
  }
  // Drafts from before refs existed get them, so revise can name their items.
  const draftsStale = (board.drafts ?? []).some(d => d.items.some(i => !i.ref))
  if (draftsStale) board = { ...board, drafts: board.drafts!.map(d => {
    if (!d.items.some(i => !i.ref)) return d
    const r = withRefs(d.items as ItemInput[], [], d.nextRef ?? 1)
    return { ...d, items: r.items as Draft['items'], nextRef: r.next }
  }) }
  if (!board.items.some(stale)) return board
  return {
    ...board,
    items: board.items.map(i => {
      if (!stale(i)) return i
      const status = STATUSES.includes(i.status) ? i.status : normalizeStatus(i.status) as Status
      // Items approved before criteria had ticks: done means accepted.
      return status === 'done' && i.acceptance?.length && !i.met ? { ...i, status, met: i.acceptance.map(() => true) } : { ...i, status }
    }),
  }
}

export const isClosed = (s: Status) => CLOSED.includes(s)

export function emptyBoard(project: string): Board {
  return { version: 1, project, nextNumber: 1, items: [] }
}

/** Accepts `T-12`, `t12`, `#12` or `12`; ids share one counter so the number alone is unique. */
export function resolveId(board: Board, ref: string | undefined | null): Item | undefined {
  if (!ref) return undefined
  const m = /(\d+)\s*$/.exec(String(ref).trim())
  if (!m) return undefined
  const n = Number(m[1])
  return board.items.find(i => Number(i.id.split('-')[1]) === n)
}

export type ItemInput = {
  ref?: string
  kind?: string
  title?: string
  description?: string
  status?: string
  priority?: string
  parent?: string
  milestone?: string
  labels?: string[]
  points?: number
  acceptance?: string[]
  due?: string
  source?: SourceRef
}

export type ItemPatch = Omit<ItemInput, 'ref' | 'kind'> & {
  /** 1-based numbers of acceptance criteria to tick or untick. */
  met?: number[]
  unmet?: number[]
  met_all?: boolean
  comment?: string
  add_labels?: string[]
  remove_labels?: string[]
}

type Result<T> = { ok: true; value: T } | { ok: false; error: string }

function pick<T extends string>(value: unknown, allowed: readonly T[], label: string): Result<T | undefined> {
  if (value === undefined || value === null || value === '') return { ok: true, value: undefined }
  const raw = String(value).toLowerCase().replace(/[\s-]+/g, '_')
  const v = (label === 'status' ? normalizeStatus(raw) : raw) as T
  return allowed.includes(v)
    ? { ok: true, value: v }
    : { ok: false, error: `${label} must be one of ${allowed.join(', ')} (got "${value}")` }
}

function checkParent(board: Board, kind: Kind, parent: Item | undefined): string | undefined {
  if (!parent) return undefined
  if (kind === 'milestone' || kind === 'epic') return `a ${kind} cannot have a parent`
  if (parent.kind === 'epic') return undefined
  if (parent.kind === 'story' && kind !== 'story') return undefined
  return `${parent.id} is a ${parent.kind}; parents must be an epic (or a story, for tasks and bugs)`
}

/**
 * Creates items in order. `ref` is a temporary name a later item in the same
 * batch can use as its `parent` or `milestone`, so an epic and its stories
 * land in one call.
 */
export function createItems(board: Board, inputs: ItemInput[], now: string, author: Comment['author'] = 'claude'):
  { board: Board; created: Item[]; errors: string[] } {
  const next: Board = { ...board, items: [...board.items] }
  const refs = new Map<string, Item>()
  const created: Item[] = []
  const errors: string[] = []
  const lookup = (r?: string) => (r ? refs.get(r) ?? resolveId(next, r) : undefined)

  inputs.forEach((input, index) => {
    const where = `item ${index + 1}${input.title ? ` ("${input.title}")` : ''}`
    const title = (input.title ?? '').trim()
    if (!title) return void errors.push(`${where}: title is required`)
    const kind = pick(input.kind ?? 'task', KINDS, 'kind')
    const status = pick(input.status, STATUSES, 'status')
    const priority = pick(input.priority, PRIORITIES, 'priority')
    for (const r of [kind, status, priority]) if (!r.ok) return void errors.push(`${where}: ${r.error}`)
    const k = (kind as { value: Kind }).value
    const parent = lookup(input.parent)
    if (input.parent && !parent) return void errors.push(`${where}: parent "${input.parent}" not found`)
    const parentError = checkParent(next, k, parent)
    if (parentError) return void errors.push(`${where}: ${parentError}`)
    const milestone = lookup(input.milestone)
    if (input.milestone && milestone?.kind !== 'milestone')
      return void errors.push(`${where}: milestone "${input.milestone}" not found`)
    if (k === 'milestone' && milestone) return void errors.push(`${where}: a milestone cannot target a milestone`)

    const item: Item = {
      id: `${PREFIX[k]}-${next.nextNumber}`,
      kind: k,
      title,
      status: (status as { value?: Status }).value ?? 'todo',
      priority: (priority as { value?: Priority }).value ?? 'medium',
      labels: [...new Set(input.labels ?? [])],
      comments: [],
      createdAt: now,
      updatedAt: now,
    }
    if (input.description) item.description = input.description
    if (parent) item.parent = parent.id
    if (milestone) item.milestone = milestone.id
    else if (parent?.milestone) item.milestone = parent.milestone
    if (typeof input.points === 'number') item.points = input.points
    if (input.acceptance?.length) item.acceptance = [...input.acceptance]
    if (input.due) item.due = input.due
    if (input.source) item.source = input.source
    if (isClosed(item.status)) item.closedAt = now
    item.activity = [{ at: now, author, text: `created as ${item.status}` }]
    next.nextNumber += 1
    next.items.push(item)
    created.push(item)
    if (input.ref) refs.set(input.ref, item)
  })
  return { board: next, created, errors }
}

export function updateItem(board: Board, id: string, patch: ItemPatch, now: string, author: Comment['author'] = 'claude'):
  Result<{ board: Board; item: Item }> {
  const found = resolveId(board, id)
  if (!found) return { ok: false, error: `no item "${id}"` }
  const item: Item = { ...found, labels: [...found.labels], comments: [...found.comments] }

  const status = pick(patch.status, STATUSES, 'status')
  if (!status.ok) return status
  const priority = pick(patch.priority, PRIORITIES, 'priority')
  if (!priority.ok) return priority

  if (patch.title !== undefined && patch.title.trim()) item.title = patch.title.trim()
  if (patch.description !== undefined) item.description = patch.description || undefined
  if (priority.value) item.priority = priority.value
  if (status.value && status.value !== item.status) {
    item.status = status.value
    item.closedAt = isClosed(status.value) ? now : undefined
    item.rank = undefined // a manual position belongs to the status it was set in
    if (status.value !== 'done') item.closedUnder = undefined
  }
  if (patch.parent !== undefined) {
    if (patch.parent === '' || patch.parent === 'none') item.parent = undefined
    else {
      const parent = resolveId(board, patch.parent)
      if (!parent) return { ok: false, error: `parent "${patch.parent}" not found` }
      if (parent.id === item.id) return { ok: false, error: 'an item cannot be its own parent' }
      const e = checkParent(board, item.kind, parent)
      if (e) return { ok: false, error: e }
      item.parent = parent.id
    }
  }
  if (patch.milestone !== undefined) {
    if (patch.milestone === '' || patch.milestone === 'none') item.milestone = undefined
    else {
      const m = resolveId(board, patch.milestone)
      if (m?.kind !== 'milestone') return { ok: false, error: `milestone "${patch.milestone}" not found` }
      if (item.kind === 'milestone') return { ok: false, error: 'a milestone cannot target a milestone' }
      item.milestone = m.id
    }
  }
  if (patch.labels) item.labels = [...new Set(patch.labels)]
  if (patch.add_labels) item.labels = [...new Set([...item.labels, ...patch.add_labels])]
  if (patch.remove_labels) item.labels = item.labels.filter(l => !patch.remove_labels!.includes(l))
  if (typeof patch.points === 'number') item.points = patch.points
  if (patch.acceptance) {
    // Keep ticks on criteria whose text survived the rewrite.
    const was = new Map((item.acceptance ?? []).map((a, n) => [a, item.met?.[n] ?? false]))
    item.acceptance = [...patch.acceptance]
    item.met = item.acceptance.map(a => was.get(a) ?? false)
  }
  const count = item.acceptance?.length ?? 0
  const bad = [...(patch.met ?? []), ...(patch.unmet ?? [])].filter(n => !Number.isInteger(n) || n < 1 || n > count)
  if (bad.length) return { ok: false, error: `${item.id} has ${count} acceptance criteria; no #${bad.join(', #')}` }
  if (count && (patch.met || patch.unmet || patch.met_all || item.status === 'done')) {
    const met = Array.from({ length: count }, (_, n) => item.met?.[n] ?? false)
    for (const n of patch.met ?? []) met[n - 1] = true
    for (const n of patch.unmet ?? []) met[n - 1] = false
    if (patch.met_all) met.fill(true)
    item.met = met
  }
  // Done is earned, never assumed: every criterion ticked, every child closed.
  if (item.status === 'done' && found.status !== 'done') {
    const block = closeBlockOf(board, item)
    if (block) return { ok: false, error: `${item.id} can't be done yet: ${block}` }
  }
  if (patch.due !== undefined) item.due = patch.due || undefined
  if (patch.comment?.trim()) item.comments.push({ at: now, author, text: patch.comment.trim() })
  item.updatedAt = now

  const changes = describeChanges(found, item)
  if (changes.length) item.activity = [...(found.activity ?? []), ...changes.map(text => ({ at: now, author, text }))].slice(-ACTIVITY_LIMIT)

  for (const k of Object.keys(item) as (keyof Item)[]) if (item[k] === undefined) delete item[k]
  return { ok: true, value: { board: { ...board, items: board.items.map(i => (i.id === item.id ? item : i)) }, item } }
}

/** Removes the item; children and targeted items are detached, not deleted, unless `cascade`. */
export function deleteItem(board: Board, id: string, cascade = false): Result<{ board: Board; removed: string[] }> {
  const found = resolveId(board, id)
  if (!found) return { ok: false, error: `no item "${id}"` }
  const removed = new Set([found.id])
  if (cascade) {
    let grew = true
    while (grew) {
      grew = false
      for (const i of board.items)
        if (!removed.has(i.id) && i.parent && removed.has(i.parent)) { removed.add(i.id); grew = true }
    }
  }
  const items = board.items
    .filter(i => !removed.has(i.id))
    .map(i => {
      const parent = i.parent && removed.has(i.parent) ? undefined : i.parent
      const milestone = i.milestone && removed.has(i.milestone) ? undefined : i.milestone
      if (parent === i.parent && milestone === i.milestone) return i
      const copy = { ...i, parent, milestone }
      if (!copy.parent) delete copy.parent
      if (!copy.milestone) delete copy.milestone
      return copy
    })
  return { ok: true, value: { board: { ...board, items }, removed: [...removed] } }
}

export type Filter = {
  kind?: string
  status?: string
  priority?: string
  parent?: string
  milestone?: string
  label?: string
  text?: string
  include_closed?: boolean
}

export function sortItems(items: Item[]): Item[] {
  return [...items].sort((a, b) =>
    STATUS_RANK[a.status] - STATUS_RANK[b.status] ||
    (a.rank ?? Infinity) - (b.rank ?? Infinity) ||
    PRIORITY_RANK[a.priority] - PRIORITY_RANK[b.priority] ||
    Number(a.id.split('-')[1]) - Number(b.id.split('-')[1]))
}

export function filterItems(board: Board, f: Filter): Item[] {
  const statuses = f.status?.split(',').map(normalizeStatus).filter(Boolean)
  const kinds = f.kind?.split(',').map(s => s.trim().toLowerCase()).filter(Boolean)
  const parent = f.parent ? resolveId(board, f.parent)?.id ?? f.parent : undefined
  const milestone = f.milestone ? resolveId(board, f.milestone)?.id ?? f.milestone : undefined
  const text = f.text?.toLowerCase()
  return sortItems(board.items.filter(i =>
    (!kinds?.length || kinds.includes(i.kind)) &&
    (statuses?.length ? statuses.includes(i.status) : f.include_closed || !isClosed(i.status)) &&
    (!f.priority || i.priority === f.priority) &&
    (!parent || i.parent === parent) &&
    (!milestone || i.milestone === milestone || (i.parent !== undefined && resolveId(board, i.parent)?.milestone === milestone)) &&
    (!f.label || i.labels.includes(f.label)) &&
    (!text || `${i.title}\n${i.description ?? ''}`.toLowerCase().includes(text))))
}

export function viewItems(board: Board, view: View): Item[] {
  switch (view) {
    case 'active': return filterItems(board, { status: 'in_progress,review,blocked,todo', kind: 'story,task,bug' })
    case 'later': return filterItems(board, { status: 'later', kind: 'story,task,bug,epic' })
    case 'epics': return filterItems(board, { kind: 'epic', include_closed: true })
    case 'milestones': return filterItems(board, { kind: 'milestone', include_closed: true })
    case 'done': return filterItems(board, { status: 'done,cancelled' }).reverse()
    case 'all': return filterItems(board, { include_closed: true })
  }
}

/** Work items under an epic (and their subtasks), or targeting a milestone directly or through an epic. */
export function membersOf(board: Board, item: Item): Item[] {
  if (item.kind === 'milestone') {
    const epics = new Set(board.items.filter(i => i.kind === 'epic' && i.milestone === item.id).map(i => i.id))
    return board.items.filter(i => i.kind !== 'milestone' && (i.milestone === item.id || (i.parent && epics.has(i.parent))))
  }
  const ids = new Set([item.id])
  const out: Item[] = []
  let grew = true
  while (grew) {
    grew = false
    for (const i of board.items)
      if (!ids.has(i.id) && i.parent && ids.has(i.parent)) { ids.add(i.id); out.push(i); grew = true }
  }
  return out
}

export function progress(board: Board, item: Item): { done: number; total: number; percent: number } {
  const work = membersOf(board, item).filter(i => i.kind !== 'epic' && i.status !== 'cancelled')
  const done = work.filter(i => i.status === 'done').length
  return { done, total: work.length, percent: work.length ? Math.round((done / work.length) * 100) : 0 }
}

export const STATUS_GLYPH: Record<Status, string> = {
  later: '·', todo: '○', in_progress: '◐', review: '◑', blocked: '✕', done: '●', cancelled: '⊘',
}

export function bar(percent: number, width = 10): string {
  const full = Math.round((percent / 100) * width)
  return '█'.repeat(full) + '░'.repeat(width - full)
}

export function line(board: Board, i: Item, { status = true }: { status?: boolean } = {}): string {
  const bits = [`${STATUS_GLYPH[i.status]} ${i.id}`]
  if (status) bits.push(`[${i.status}]`)
  if (i.priority !== 'medium') bits.push(`!${i.priority}`)
  bits.push(i.title)
  if (i.kind === 'epic' || i.kind === 'milestone') {
    const p = progress(board, i)
    bits.push(`(${p.done}/${p.total} done${i.due ? `, due ${i.due}` : ''})`)
    if (readyToClose(board, i)) bits.push('· ready to close')
  } else {
    const ctx = [i.parent, i.milestone].filter(Boolean).join(' ')
    if (ctx) bits.push(`<${ctx}>`)
    const a = acceptanceProgress(i)
    if (a) bits.push(`✓${a.met}/${a.total}`)
    if (i.points !== undefined) bits.push(`${i.points}pt`)
    if (i.due) bits.push(`due ${i.due}`)
  }
  if (i.labels.length) bits.push(i.labels.map(l => `#${l}`).join(' '))
  return bits.join(' ')
}

export function detail(board: Board, i: Item, { acceptance = true, members: listMembers = true, history = true, notes = true, code = true, nowMs = Date.parse(i.updatedAt) }: { acceptance?: boolean; members?: boolean; history?: boolean; notes?: boolean; code?: boolean; nowMs?: number } = {}): string {
  const out = [`${i.id} · ${i.kind} · ${i.status} · ${i.priority} priority`, `# ${i.title}`]
  if (i.description) out.push('', i.description)
  const meta: string[] = []
  if (i.parent) meta.push(`parent: ${i.parent} ${resolveId(board, i.parent)?.title ?? ''}`.trim())
  if (i.milestone) meta.push(`milestone: ${i.milestone} ${resolveId(board, i.milestone)?.title ?? ''}`.trim())
  if (i.points !== undefined) meta.push(`points: ${i.points}`)
  if (i.due) meta.push(`due: ${i.due}`)
  if (i.labels.length) meta.push(`labels: ${i.labels.join(', ')}`)
  meta.push(`created: ${i.createdAt}`, `updated: ${i.updatedAt}`)
  if (i.closedAt) meta.push(`closed: ${i.closedAt}${i.closedUnder ? ` by Claude, under your standing approval for ${i.closedUnder}` : ''}`)
  out.push('', ...meta)
  if (i.acceptance?.length && acceptance) {
    const a = acceptanceProgress(i)!
    out.push('', `Acceptance criteria (${a.met}/${a.total} met):`, ...i.acceptance.map((c, n) => `${n + 1}. [${i.met?.[n] ? 'x' : ' '}] ${c}`))
  }
  if (i.kind === 'epic' || i.kind === 'milestone' || i.kind === 'story') {
    const members = sortItems(membersOf(board, i))
    if (members.length) {
      const p = progress(board, i)
      out.push('', `Progress: ${bar(p.percent)} ${p.percent}% (${p.done}/${p.total})`, ...(listMembers ? members.map(m => `  ${line(board, m)}`) : []))
    }
  }
  if (code) out.push(...codeText(board, i, nowMs))
  const when = (c: Comment) => `${c.at.slice(0, 16).replace('T', ' ')} ${c.author}`
  if (i.comments.length && notes) out.push('', 'Notes:', ...i.comments.map(c => `- ${when(c)}: ${c.text}`))
  if (i.activity?.length && history) out.push('', 'History:', ...i.activity.slice(-10).map(c => `- ${when(c)}: ${c.text}`))
  return out.join('\n')
}

export function summary(board: Board): string {
  const open = board.items.filter(i => !isClosed(i.status))
  if (board.items.length === 0) return 'The board is empty. Create milestones, epics, stories, tasks or bugs to start.'
  const out: string[] = []
  const count = (s: Status) => open.filter(i => i.status === s && i.kind !== 'epic' && i.kind !== 'milestone').length
  out.push(`Open work: ${count('in_progress')} in progress, ${count('review')} in review, ${count('blocked')} blocked, ${count('todo')} to do, ${count('later')} for later. ${board.items.filter(i => i.status === 'done').length} done.`)
  const ms = sortItems(board.items.filter(i => i.kind === 'milestone' && !isClosed(i.status)))
  if (ms.length) out.push('', 'Milestones:', ...ms.map(m => `  ${line(board, m)}`))
  const epics = sortItems(board.items.filter(i => i.kind === 'epic' && !isClosed(i.status)))
  if (epics.length) out.push('', 'Epics:', ...epics.map(e => `  ${line(board, e)}`))
  const drafts = (board.drafts ?? []).filter(d => d.status === 'open')
  if (drafts.length) out.push('', `Drafts waiting for the user's review: ${drafts.map(d => `${d.id} ${d.topic} (${d.items.length} items${(d.questions ?? []).some(q => !q.answer) ? `, ${(d.questions ?? []).filter(q => !q.answer).length} open questions` : ''})`).join(', ')}`)
  const byClaude = board.items.filter(i => i.closedUnder && i.status === 'done').sort((a, b) => (b.closedAt ?? '').localeCompare(a.closedAt ?? '')).slice(0, 8)
  if (byClaude.length) out.push('', `Closed by Claude under standing approval (latest): ${byClaude.map(i => `${i.id} ${i.title} (${i.closedUnder})`).join(', ')}`)
  const ready = closable(board)
  if (ready.length) out.push('', `Ready to close (all work done; ask the user before closing): ${ready.map(i => `${i.id} ${i.title}`).join(', ')}`)
  const active = viewItems(board, 'active')
  if (active.length) out.push('', 'Active work:', ...active.slice(0, 25).map(i => `  ${line(board, i)}`))
  if (active.length > 25) out.push(`  ...and ${active.length - 25} more`)
  return out.join('\n')
}

/** Highest-priority open work item: in progress first, then to do. */
export function nextUp(board: Board): Item | undefined {
  return filterItems(board, { status: 'in_progress,todo', kind: 'story,task,bug' })
    .find(i => !board.items.some(c => c.parent === i.id && !isClosed(c.status)))
}

/** FNV-1a over the board's saved text: tells undo whether the board moved on since a change. */
export function fingerprint(text: string): string {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(16)
}

export const serialize = (board: Board) => JSON.stringify(board, null, 2) + '\n'

/** What undo compares: the board without its event log, which undo itself appends to. */
export const contentPrint = (board: Board) => fingerprint(JSON.stringify({ ...board, log: undefined }))

export const STATUS_LABEL: Record<Status, string> = {
  later: 'Later', todo: 'To do', in_progress: 'In progress', review: 'Review',
  blocked: 'Blocked', done: 'Done', cancelled: 'Cancelled',
}

/** Splits sorted items into status groups, in status order, leaving out empty ones. */
export function groupByStatus(items: Item[]): { status: Status; items: Item[] }[] {
  return [...STATUSES]
    .sort((a, b) => STATUS_RANK[a] - STATUS_RANK[b])
    .map(status => ({ status, items: items.filter(i => i.status === status) }))
    .filter(g => g.items.length > 0)
}

/** What deleting an item touches: children it would take with it (cascade), and items that only point at it. */
export function dependents(board: Board, item: Item): { children: Item[]; targeted: Item[] } {
  const r = deleteItem(board, item.id, true)
  const removed = new Set(r.ok ? r.value.removed : [])
  removed.delete(item.id)
  return {
    children: board.items.filter(i => removed.has(i.id)),
    targeted: board.items.filter(i => i.milestone === item.id && !removed.has(i.id)),
  }
}

/**
 * Whether an item matches a search: every word must hit. `#word` matches a
 * label, a bare id (`S-12`, `12`) matches that item, anything else matches
 * the id, title or description.
 */
export function matchesQuery(item: Item, query: string): boolean {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean)
  const id = item.id.toLowerCase()
  const text = `${id}\n${item.title}\n${item.description ?? ''}`.toLowerCase()
  return words.every(w => {
    if (w.startsWith('#')) return w.length === 1 || item.labels.some(l => l.toLowerCase().startsWith(w.slice(1)))
    if (/^#?\d+$/.test(w)) return id.split('-')[1] === w.replace('#', '') || text.includes(w)
    return text.includes(w)
  })
}

// `blocked` says why the move can't be made yet; a surface draws it unpressable.
export type Action = { status: Status; label: string; short: string; hotkey: string; primary?: true; blocked?: string }

const act = (status: Status, label: string, short: string, hotkey: string, primary?: true): Action =>
  primary ? { status, label, short, hotkey, primary } : { status, label, short, hotkey }

/**
 * The moves that make sense from an item's current status, main one first,
 * labelled as what will happen. Epics and milestones only open, park or close:
 * their progress comes from their children.
 */
export function actionsFor(item: Item, ready = false, closeBlock?: string): Action[] {
  const all = movesFor(item, ready)
  return closeBlock ? all.map(a => (a.status === 'done' ? { ...a, blocked: closeBlock } : a)) : all
}

function movesFor(item: Item, ready: boolean): Action[] {
  const container = item.kind === 'epic' || item.kind === 'milestone'
  if (isClosed(item.status)) return [act('todo', 'Reopen', 'reopen', 't')]
  if (container) return [
    ready ? act('done', 'Close it (all done)', 'close', 'd', true) : act('done', 'Mark done', 'done', 'd'),
    ...(item.status === 'later' ? [act('todo', 'Plan it (to do)', 'plan', 't')] : [act('later', 'Park for later', 'later', 'l')]),
  ]
  switch (item.status) {
    case 'later': return [act('todo', 'Plan it (to do)', 'plan', 't', true), act('in_progress', 'Start now', 'start', 's'), act('done', 'Mark done', 'done', 'd')]
    case 'todo': return [act('in_progress', 'Start', 'start', 's', true), act('done', 'Mark done', 'done', 'd'), act('blocked', 'Mark blocked', 'block', 'b'), act('later', 'Park for later', 'later', 'l')]
    case 'in_progress': return [act('review', 'Send to review', 'review', 'r', true), act('done', 'Mark done', 'done', 'd'), act('blocked', 'Mark blocked', 'block', 'b'), act('todo', 'Stop (back to to do)', 'stop', 't')]
    case 'review': return [act('done', 'Approve (done)', 'approve', 'd', true), act('in_progress', 'Send back (in progress)', 'send back', 's'), act('blocked', 'Mark blocked', 'block', 'b')]
    case 'blocked': return [act('in_progress', 'Unblock and start', 'unblock', 's', true), act('todo', 'Unblock (to do)', 'to do', 't'), act('done', 'Mark done', 'done', 'd')]
    default: return []
  }
}

/**
 * Why an item can't be closed as done yet, or undefined when it can: a work
 * item needs every acceptance criterion ticked, and an epic or milestone needs
 * all its work closed. A criterion that no longer applies is edited out.
 */
export function closeBlockOf(board: Board, item: Item): string | undefined {
  if (item.kind === 'epic' || item.kind === 'milestone') {
    const p = progress(board, item)
    const open = p.total - p.done
    return open > 0 ? `${open} of ${p.total} items under it ${open === 1 ? 'is' : 'are'} still open` : undefined
  }
  const a = acceptanceProgress(item)
  if (!a || a.open.length === 0) return undefined
  return `acceptance ${a.open.length === 1 ? 'criterion' : 'criteria'} ${a.open.map(n => `#${n}`).join(', ')} ${a.open.length === 1 ? 'is' : 'are'} not met. Tick ${a.open.length === 1 ? 'it' : 'them'} first, or edit out one that no longer applies`
}

export function acceptanceProgress(i: Item): { met: number; total: number; open: number[] } | undefined {
  if (!i.acceptance?.length) return undefined
  const open = i.acceptance.map((_, n) => n + 1).filter(n => !i.met?.[n - 1])
  return { met: i.acceptance.length - open.length, total: i.acceptance.length, open }
}

export type Move = 'up' | 'down' | 'top' | 'bottom'
export const MOVES: readonly Move[] = ['up', 'down', 'top', 'bottom']

const rankGroup = (i: Item) => (i.kind === 'epic' || i.kind === 'milestone' ? i.kind : 'work')

/** The items an item is ordered among: same status, and work items, epics or milestones alike. */
export function siblings(board: Board, item: Item): Item[] {
  return sortItems(board.items.filter(i => i.status === item.status && rankGroup(i) === rankGroup(item)))
}

/** Moves an item within its siblings and numbers the whole group, so the order sticks. */
export function moveItem(board: Board, id: string, move: Move, now: string, author: Comment['author'] = 'claude'): Result<{ board: Board; item: Item; moved: boolean }> {
  const found = resolveId(board, id)
  if (!found) return { ok: false, error: `no item "${id}"` }
  const group = siblings(board, found)
  const from = group.findIndex(i => i.id === found.id)
  const to = move === 'top' ? 0 : move === 'bottom' ? group.length - 1 : move === 'up' ? Math.max(0, from - 1) : Math.min(group.length - 1, from + 1)
  if (to === from) return { ok: true, value: { board, item: found, moved: false } }
  const order = [...group]
  order.splice(to, 0, ...order.splice(from, 1))
  const ranks = new Map(order.map((i, n) => [i.id, n]))
  const items = board.items.map(i => {
    if (!ranks.has(i.id)) return i
    if (i.id !== found.id) return { ...i, rank: ranks.get(i.id)! }
    const activity = [...(i.activity ?? []), { at: now, author, text: `moved ${move}` }].slice(-ACTIVITY_LIMIT)
    return { ...i, rank: ranks.get(i.id)!, updatedAt: now, activity }
  })
  const next = { ...board, items }
  return { ok: true, value: { board: next, item: resolveId(next, found.id)!, moved: true } }
}

/** The rows shown under an expanded epic, story or milestone: its members, nested one level for subtasks. */
export function childRows(board: Board, item: Item): { item: Item; depth: number }[] {
  const members = sortItems(membersOf(board, item))
  if (item.kind === 'milestone') return members.map(m => ({ item: m, depth: 1 }))
  const direct = members.filter(m => m.parent === item.id)
  return direct.flatMap(d => [{ item: d, depth: 1 }, ...members.filter(m => m.parent === d.id).map(m => ({ item: m, depth: 2 }))])
}

/** Plain-words lines for what an update changed, for the item's history. */
export function describeChanges(before: Item, after: Item): string[] {
  const out: string[] = []
  const name = (id?: string) => (id ? `${id}` : 'none')
  if (before.status !== after.status) out.push(`status ${before.status} → ${after.status}`)
  if (before.priority !== after.priority) out.push(`priority ${before.priority} → ${after.priority}`)
  if (before.title !== after.title) out.push(`renamed from "${before.title}"`)
  if ((before.description ?? '') !== (after.description ?? '')) out.push('description edited')
  if (before.parent !== after.parent) out.push(`parent ${name(before.parent)} → ${name(after.parent)}`)
  if (before.milestone !== after.milestone) out.push(`milestone ${name(before.milestone)} → ${name(after.milestone)}`)
  if (before.points !== after.points) out.push(`points ${before.points ?? '-'} → ${after.points ?? '-'}`)
  if ((before.due ?? '') !== (after.due ?? '')) out.push(`due ${before.due ?? '-'} → ${after.due ?? '-'}`)
  if (before.labels.join() !== after.labels.join()) out.push(`labels: ${after.labels.join(', ') || 'none'}`)
  if ((before.acceptance ?? []).join('\n') !== (after.acceptance ?? []).join('\n')) out.push('acceptance criteria rewritten')
  else {
    const ticked = (after.met ?? []).map((m, n) => (m && !before.met?.[n] ? n + 1 : 0)).filter(Boolean)
    const unticked = (before.met ?? []).map((m, n) => (m && !after.met?.[n] ? n + 1 : 0)).filter(Boolean)
    if (ticked.length) out.push(`ticked criteria #${ticked.join(', #')}`)
    if (unticked.length) out.push(`unticked criteria #${unticked.join(', #')}`)
  }
  if (after.comments.length > before.comments.length) out.push('added a note')
  return out
}

/**
 * Marks a change with the session that made it: new item history entries get
 * the session id, and items that disappeared go into the board log.
 */
export function stamp(before: Board, after: Board, at: string, session: string, author: Comment['author']): Board {
  const kept = new Set(after.items.map(i => i.id))
  const removed = before.items.filter(i => !kept.has(i.id))
  const items = after.items.map(i => {
    if (!i.activity?.some(a => a.at === at && !a.session)) return i
    return { ...i, activity: i.activity.map(a => (a.at === at && !a.session ? { ...a, session } : a)) }
  })
  const log = removed.length
    ? [...(after.log ?? []), ...removed.map(i => ({ at, author, session, text: `deleted ${i.id} "${i.title}"` }))].slice(-LOG_LIMIT)
    : after.log
  return log ? { ...after, items, log } : { ...after, items }
}

/**
 * What changed since a moment, by anyone but this session's Claude: the user
 * (in any session, the pane or the web app) and other Claude sessions.
 * One line per item, newest board state; undefined when nothing changed.
 */
export function digest(board: Board, since: string, session: string, limit = 15): string | undefined {
  const theirs = (c: Comment) => c.at > since && (c.author === 'user' || c.session !== session)
  const who = (c: Comment) => (c.author === 'user' ? '' : ' (another Claude session)')
  const lines: string[] = []
  for (const i of sortItems(board.items)) {
    const changes = (i.activity ?? []).filter(theirs)
    if (!changes.length) continue
    const users = [...new Set(changes.map(who))]
    lines.push(`- ${i.id} "${i.title}" [now ${i.status}]: ${changes.map(c => c.text).join('; ')}${users.length === 1 ? users[0] : ''}`)
  }
  for (const c of (board.log ?? []).filter(theirs)) lines.push(`- ${c.text}${who(c)}`)
  for (const d of (board.drafts ?? []).filter(d => d.status === 'open')) {
    const edits = (d.log ?? []).filter(theirs)
    if (edits.length) lines.push(`- draft ${d.id} "${d.topic}": ${edits.map(c => c.text).join('; ')}${[...new Set(edits.map(who))].length === 1 ? who(edits[0]!) : ''} (build on these; don't undo them without asking)`)
  }
  if (!lines.length) return undefined
  const shown = lines.slice(0, limit)
  const ready = closable(board)
  return [
    'Backlog: the board changed since your last turn (by the user unless noted). Take this into account:',
    ...shown,
    ...(lines.length > limit ? [`(+${lines.length - limit} more; call mcp__backlog__summary for the full picture)`] : []),
    ...(ready.length ? [`Ready to close (all work done): ${ready.map(i => i.id).join(', ')}. Mention it to the user; closing is their call.`] : []),
    ...((board.drafts ?? []).filter(d => d.status === 'open' && openQuestions(d).length).map(d => `Draft ${d.id} "${d.topic}" has ${openQuestions(d).length} open question${openQuestions(d).length === 1 ? '' : 's'}: ${openQuestions(d).map(q => `${q.id} ${q.text}`).join(' | ')}`)),
  ].join('\n')
}

/**
 * Drops an item at a position among its siblings, changing status first if
 * asked: what dragging a card to a spot in a column does.
 */
export function placeItem(board: Board, id: string, status: Status | undefined, index: number, now: string, author: Comment['author'] = 'user'): Result<{ board: Board; item: Item }> {
  let current = board
  const found = resolveId(board, id)
  if (!found) return { ok: false, error: `no item "${id}"` }
  if (status && status !== found.status) {
    const r = updateItem(current, found.id, { status }, now, author)
    if (!r.ok) return r
    current = r.value.board
  }
  const item = resolveId(current, found.id)!
  const order = siblings(current, item).filter(i => i.id !== item.id)
  order.splice(Math.max(0, Math.min(index, order.length)), 0, item)
  const ranks = new Map(order.map((i, n) => [i.id, n]))
  const items = current.items.map(i => (ranks.has(i.id) ? { ...i, rank: ranks.get(i.id)! } : i))
  const next = { ...current, items }
  return { ok: true, value: { board: next, item: resolveId(next, found.id)! } }
}

/** An open epic or milestone whose work is all done: worth closing, though closing stays the user's call. */
export function readyToClose(board: Board, item: Item): boolean {
  if ((item.kind !== 'epic' && item.kind !== 'milestone') || isClosed(item.status)) return false
  const p = progress(board, item)
  return p.total > 0 && p.done === p.total
}

export const closable = (board: Board) => sortItems(board.items.filter(i => readyToClose(board, i)))

export type CommitLink = { id: string; closes: boolean }

/** The items a commit message names: any id (S-12, T-4…), and whether it says it fixes, closes or resolves them. */
export function commitLinks(message: string): CommitLink[] {
  const found = new Map<string, boolean>()
  for (const m of message.matchAll(/\b(?:(fix(?:e[sd])?|close[sd]?|resolve[sd]?)\s+)?([MESTB])-(\d+)\b/gi)) {
    const id = `${m[2]!.toUpperCase()}-${m[3]}`
    found.set(id, (found.get(id) ?? false) || m[1] !== undefined)
  }
  return [...found].map(([id, closes]) => ({ id, closes }))
}

/** Notes a commit on each item it names; items it fixes go to review. Already-noted commits are skipped. */
export function linkCommit(board: Board, hash: string, subject: string, message: string, now: string): { board: Board; linked: string[] } {
  const short = hash.slice(0, 7)
  let current = board
  const linked: string[] = []
  for (const { id, closes } of commitLinks(message)) {
    const item = resolveId(current, id)
    if (!item || item.comments.some(c => c.text.includes(short))) continue
    const toReview = closes && !isClosed(item.status) && item.status !== 'review' && item.kind !== 'epic' && item.kind !== 'milestone'
    const r = updateItem(current, item.id, { comment: `commit ${short}: ${subject}`, ...(toReview ? { status: 'review' } : {}) }, now, 'claude')
    if (!r.ok) continue
    current = r.value.board
    linked.push(`${item.id}${toReview ? ' → review' : ''}`)
  }
  return { board: current, linked }
}

/** How deep each proposed item sits, following `parent` refs within the proposal (existing ids sit at the top). */
export function planDepths(items: ItemInput[]): number[] {
  const byRef = new Map(items.map((it, n) => [it.ref, n] as const).filter(([r]) => r))
  const depth = (n: number, seen = new Set<number>()): number => {
    const parent = items[n]?.parent
    const at = parent ? byRef.get(parent) : undefined
    if (at === undefined || seen.has(at)) return 0
    seen.add(n)
    return 1 + depth(at, seen)
  }
  return items.map((_, n) => depth(n))
}

/** The items the user kept: unticked ones go, and so does anything under them in the proposal. */
export function keptItems(items: ItemInput[], include: boolean[]): ItemInput[] {
  const dropped = new Set<string>()
  const kept: ItemInput[] = []
  items.forEach((it, n) => {
    const underDropped = (it.parent && dropped.has(it.parent)) || (it.milestone && dropped.has(it.milestone))
    if (!include[n] || underDropped) {
      if (it.ref) dropped.add(it.ref)
      return
    }
    kept.push(it)
  })
  return kept
}

/**
 * The existing epic or milestone a proposal sits under, if every item in it
 * leads to one (through its parent or milestone, or a proposed parent that does).
 * Undefined when any item would land outside it, or the items point at different ones.
 */
export function proposalScope(board: Board, items: ItemInput[]): string | undefined {
  const byRef = new Map(items.filter(it => it.ref).map(it => [it.ref!, it] as const))
  const anchor = (it: ItemInput, seen = new Set<ItemInput>()): string[] => {
    if (seen.has(it)) return []
    seen.add(it)
    const out: string[] = []
    for (const link of [it.parent, it.milestone]) {
      if (!link) continue
      const proposed = byRef.get(link)
      if (proposed) out.push(...anchor(proposed, seen))
      else {
        const existing = resolveId(board, link)
        if (existing) out.push(...ancestorsOf(board, existing).map(i => i.id))
      }
    }
    return out
  }
  const lists = items.map(it => anchor(it))
  if (lists.some(l => !l.length)) return undefined
  // The nearest scope every item shares.
  return lists[0]!.find(id => lists.every(l => l.includes(id)))
}

/** An item, then its parent chain, then the milestones along the way: what it sits under. */
export function ancestorsOf(board: Board, item: Item): Item[] {
  const out: Item[] = []
  let current: Item | undefined = item
  while (current && !out.includes(current)) {
    out.push(current)
    current = current.parent ? resolveId(board, current.parent) : undefined
  }
  for (const i of [...out]) {
    const m = i.milestone ? resolveId(board, i.milestone) : undefined
    if (m && !out.includes(m)) out.push(m)
  }
  return out.filter(i => i.kind === 'epic' || i.kind === 'milestone' || i.kind === 'story')
}

export function allowedFor(board: Board, items: ItemInput[]): string | undefined {
  const scope = proposalScope(board, items)
  if (!scope) return undefined
  const granted = new Set((board.allow ?? []).filter(a => a.what === 'plans').map(a => a.scope))
  const item = resolveId(board, scope)
  return item && ancestorsOf(board, item).some(i => granted.has(i.id)) ? [...granted].find(g => ancestorsOf(board, item).some(i => i.id === g)) : undefined
}

export const DRAFTS_KEPT_CLOSED = 20

export const openDrafts = (board: Board) => (board.drafts ?? []).filter(d => d.status === 'open')

export function findDraft(board: Board, id?: string | null): Draft | undefined {
  const open = openDrafts(board)
  if (!id) return open.at(-1)
  const n = String(id).match(/(\d+)\s*$/)?.[1]
  return (board.drafts ?? []).find(d => d.id.toLowerCase() === String(id).toLowerCase() || (n !== undefined && d.id === `D-${n}`))
}

/** What a draft is about when no topic is given: its first epic or milestone, else its first item. */
export function draftTopic(items: ItemInput[]): string {
  return (items.find(i => i.kind === 'epic' || i.kind === 'milestone') ?? items[0])?.title?.trim() || 'Untitled plan'
}

export function addDraft(board: Board, items: ItemInput[], now: string, topic = draftTopic(items)): { board: Board; draft: Draft } {
  const n = board.nextDraft ?? 1
  const refs = withRefs(items)
  const draft: Draft = { id: `D-${n}`, topic, status: 'open', items: refs.items as Draft['items'], include: items.map(() => true), createdAt: now, updatedAt: now, nextRef: refs.next }
  return { board: { ...board, nextDraft: n + 1, drafts: [...(board.drafts ?? []), draft] }, draft }
}

export function changeDraft(board: Board, id: string, fn: (d: Draft) => Draft): Board {
  return { ...board, drafts: (board.drafts ?? []).map(d => (d.id === id ? fn(d) : d)) }
}

/** Closes a draft and trims old closed ones, so the board doesn't keep every plan forever. */
export function closeDraft(board: Board, id: string, status: 'accepted' | 'discarded', now: string, created?: string[]): Board {
  const next = changeDraft(board, id, d => ({ ...d, status, updatedAt: now, ...(created ? { created } : {}) }))
  const closed = (next.drafts ?? []).filter(d => d.status !== 'open')
  const drop = new Set(closed.slice(0, Math.max(0, closed.length - DRAFTS_KEPT_CLOSED)).map(d => d.id))
  return { ...next, drafts: (next.drafts ?? []).filter(d => !drop.has(d.id)) }
}

/** Every draft item gets a ref, so later revisions can name it. Existing refs are kept. */
export function withRefs(items: ItemInput[], taken: string[] = [], start = 1): { items: ItemInput[]; next: number } {
  const used = new Set([...taken, ...items.map(i => i.ref).filter(Boolean) as string[]])
  let n = start
  const out = items.map(it => {
    if (it.ref) return it
    while (used.has(`i${n}`)) n++
    used.add(`i${n}`)
    return { ...it, ref: `i${n++}` }
  })
  return { items: out, next: n }
}

export const DRAFT_LOG_LIMIT = 60
const DRAFT_FIELDS = ['kind', 'title', 'description', 'status', 'priority', 'parent', 'milestone', 'labels', 'points', 'acceptance', 'due'] as const

export type DraftOps = {
  /** New open questions; answers by question id; decisions settled. */
  ask?: string[]
  answer?: { id: string; text: string }[]
  decide?: string[]
  add?: ItemInput[]
  update?: (Partial<ItemInput> & { ref: string })[]
  remove?: string[]
  order?: string[]
  force?: boolean
}

/**
 * Applies Claude's or the user's edits to a draft by ref. Claude's changes to
 * fields the user edited since Claude last touched them are refused unless
 * forced, and reported as conflicts; the user's edits are remembered for that.
 */
export function reviseDraft(draft: Draft, ops: DraftOps, author: Comment['author'], now: string, session?: string):
  { draft: Draft; changes: string[]; conflicts: string[]; errors: string[] } {
  let items = [...draft.items] as ItemInput[]
  let include = [...draft.include]
  const userEdited: Record<string, string[]> = { ...(draft.userEdited ?? {}) }
  const changes: string[] = []
  const conflicts: string[] = []
  const errors: string[] = []
  const name = (it: ItemInput) => `${it.kind ?? 'item'} "${it.title}"`
  const indexOf = (ref: string) => items.findIndex(i => i.ref === ref)

  for (const ref of ops.remove ?? []) {
    const at = indexOf(ref)
    if (at < 0) { errors.push(`no item with ref "${ref}"`); continue }
    changes.push(`− ${name(items[at]!)}`)
    items.splice(at, 1)
    include.splice(at, 1)
    delete userEdited[ref]
  }
  for (const u of ops.update ?? []) {
    const at = indexOf(u.ref)
    if (at < 0) { errors.push(`no item with ref "${u.ref}"`); continue }
    const before = items[at]!
    const next: ItemInput = { ...before }
    const touched: string[] = []
    for (const f of DRAFT_FIELDS) {
      if (!(f in u) || u[f] === undefined) continue
      if (JSON.stringify(before[f]) === JSON.stringify(u[f])) continue
      if (author === 'claude' && !ops.force && userEdited[u.ref]?.includes(f)) {
        conflicts.push(`${name(before)}: the user changed ${f} to ${JSON.stringify(before[f])}; kept theirs (ask them, then pass force to change it)`)
        continue
      }
      ;(next as Record<string, unknown>)[f] = u[f]
      touched.push(f)
    }
    if (!touched.length) continue
    items[at] = next
    changes.push(`~ ${name(next)}: ${touched.join(', ')}`)
    if (author === 'user') userEdited[u.ref] = [...new Set([...(userEdited[u.ref] ?? []), ...touched])]
    else userEdited[u.ref] = (userEdited[u.ref] ?? []).filter(f => !touched.includes(f))
    if (!userEdited[u.ref]?.length) delete userEdited[u.ref]
  }
  let nextRef = draft.nextRef ?? 1
  if (ops.add?.length) {
    const fresh = withRefs(ops.add, items.map(i => i.ref!).filter(Boolean), nextRef)
    nextRef = fresh.next
    for (const it of fresh.items) {
      if (!it.title?.trim()) { errors.push('an added item has no title'); continue }
      items.push(it)
      include.push(true)
      changes.push(`+ ${name(it)}${it.parent ? ` under ${it.parent}` : ''}`)
      if (author === 'user' && it.ref) userEdited[it.ref] = ['title']
    }
  }
  if (ops.order?.length) {
    const rank = new Map(ops.order.map((r, n) => [r, n]))
    const pairs = items.map((it, n) => ({ it, keep: include[n]!, n }))
    pairs.sort((a, b) => (rank.get(a.it.ref!) ?? 1e9) - (rank.get(b.it.ref!) ?? 1e9) || a.n - b.n)
    items = pairs.map(p => p.it)
    include = pairs.map(p => p.keep)
    changes.push('reordered')
  }
  let questions = [...(draft.questions ?? [])]
  let decisions = [...(draft.decisions ?? [])]
  let nextQuestion = draft.nextQuestion ?? 1
  for (const text of ops.ask ?? []) {
    if (!text?.trim()) continue
    questions.push({ id: `q${nextQuestion++}`, text: text.trim(), at: now })
    changes.push(`? asked: ${text.trim()}`)
  }
  for (const a of ops.answer ?? []) {
    const q = questions.find(q => q.id === a.id)
    if (!q) { errors.push(`no question "${a.id}"`); continue }
    questions = questions.map(x => (x.id === a.id ? { ...x, answer: a.text.trim(), answeredAt: now } : x))
    changes.push(`= answered ${q.id}: ${a.text.trim()}`)
  }
  for (const text of ops.decide ?? []) {
    if (!text?.trim()) continue
    decisions.push({ text: text.trim(), at: now, author })
    changes.push(`! decided: ${text.trim()}`)
  }
  // Parents named by ref must still exist in the draft or on the board (checked at accept).
  const refs = new Set(items.map(i => i.ref))
  for (const it of items) if (it.parent && /^i\d+$|^[a-z]/.test(it.parent) && !refs.has(it.parent) && !/^[MESTB]-\d+$/i.test(it.parent)) errors.push(`${name(it)}: parent "${it.parent}" is not in the draft`)

  const log = changes.length
    ? [...(draft.log ?? []), ...changes.map(text => ({ at: now, author, text, ...(session ? { session } : {}) }))].slice(-DRAFT_LOG_LIMIT)
    : draft.log
  return {
    draft: {
      ...draft, items: items as Draft['items'], include, userEdited, nextRef, updatedAt: changes.length ? now : draft.updatedAt,
      ...(questions.length ? { questions, nextQuestion } : {}), ...(decisions.length ? { decisions } : {}), ...(log ? { log } : {}),
    },
    changes, conflicts, errors,
  }
}

export const COMMITS_KEPT = 50

export type GitCommit = { hash: string; subject: string; body: string; author: string; at: string; branch?: string }

/** The item ids a branch name carries: feature/S-12-login, s-12, bug/b-7 (dash or underscore, any case). */
export function branchIds(name: string): string[] {
  const out = new Set<string>()
  for (const m of name.matchAll(/(?:^|[^A-Za-z0-9])([mestbMESTB])[-_](\d+)(?![0-9])/g)) out.add(`${m[1]!.toUpperCase()}-${m[2]}`)
  return [...out]
}

/**
 * Brings items' code records up to date with what git shows: commits that name
 * an item (newest first, once each), and the branches whose names carry its id
 * (the full current list, so deleted branches drop off). A commit that fixes an
 * item sends it to review the first time it is seen.
 */
export function applyGit(board: Board, commits: GitCommit[], branches: string[] | undefined, now: string, authorOf: (c: GitCommit) => Comment['author'] = () => 'user'):
  { board: Board; linked: string[] } {
  const linked: string[] = []
  let items = board.items
  const byId = (id: string) => items.findIndex(i => i.id === resolveId({ ...board, items }, id)?.id)
  const put = (index: number, item: Item) => { items = items.map((it, n) => (n === index ? item : it)) }

  for (const c of [...commits].sort((a, b) => a.at.localeCompare(b.at))) {
    for (const { id, closes } of commitLinks(`${c.subject}\n${c.body}`)) {
      const at = byId(id)
      if (at < 0) continue
      const item = items[at]!
      const code: CodeRecord = item.code ?? { branches: [], commits: [] }
      const ref: CommitRef = { hash: c.hash, subject: c.subject, author: c.author, at: c.at, ...(c.branch ? { branch: c.branch } : {}) }
      const known = code.commits.findIndex(k => c.hash.startsWith(k.hash))
      if (known >= 0) {
        // A record from a migrated note (short hash): fill in what git knows, quietly.
        if (code.commits[known]!.hash.length < c.hash.length) put(at, { ...item, code: { ...code, commits: code.commits.map((k, n) => (n === known ? ref : k)) } })
        continue
      }
      const toReview = closes && !isClosed(item.status) && item.status !== 'review' && item.kind !== 'epic' && item.kind !== 'milestone'
      const entry = { at: now, author: authorOf(c), text: `commit ${c.hash.slice(0, 7)} by ${c.author}: ${c.subject}${toReview ? ' (fixes it: status → review)' : ''}` }
      put(at, {
        ...item,
        ...(toReview ? { status: 'review' as Status, rank: undefined } : {}),
        code: { ...code, commits: [ref, ...code.commits].slice(0, COMMITS_KEPT) },
        activity: [...(item.activity ?? []), entry].slice(-ACTIVITY_LIMIT),
      })
      linked.push(`${item.id}${toReview ? ' → review' : ''}`)
    }
  }
  if (branches) {
    const named = new Map<string, string[]>()
    for (const b of branches) for (const id of branchIds(b)) named.set(id, [...(named.get(id) ?? []), b])
    items = items.map(i => {
      const now_ = (named.get(i.id) ?? []).sort()
      const before = i.code?.branches ?? []
      if (now_.join() === before.join()) return i
      if (!now_.length && !i.code) return i
      return { ...i, code: { commits: i.code?.commits ?? [], branches: now_ } }
    })
  }
  return { board: items === board.items ? board : { ...board, items }, linked: [...new Set(linked)] }
}

/** "3h ago" style, coarse on purpose: when a commit happened, not to the second. */
export function ago(at: string, nowMs: number): string {
  const s = Math.max(0, Math.round((nowMs - Date.parse(at)) / 1000))
  if (!Number.isFinite(s)) return at
  if (s < 90) return 'just now'
  if (s < 3600) return `${Math.round(s / 60)}m ago`
  if (s < 86_400) return `${Math.round(s / 3600)}h ago`
  if (s < 30 * 86_400) return `${Math.round(s / 86_400)}d ago`
  return at.slice(0, 10)
}

/** An item's code history; epics and milestones roll up their members', newest first, each commit once. */
export function codeOf(board: Board, item: Item): { branches: string[]; commits: CommitRef[] } {
  const sources = item.kind === 'epic' || item.kind === 'milestone' ? [item, ...membersOf(board, item)] : [item]
  const seen = new Set<string>()
  const commits: CommitRef[] = []
  for (const c of sources.flatMap(i => i.code?.commits ?? []).sort((a, b) => b.at.localeCompare(a.at))) {
    if (seen.has(c.hash)) continue
    seen.add(c.hash)
    commits.push(c)
  }
  return { branches: [...new Set(sources.flatMap(i => i.code?.branches ?? []))].sort(), commits }
}

export function codeText(board: Board, item: Item, nowMs: number, limit = 8): string[] {
  const { branches, commits } = codeOf(board, item)
  if (!branches.length && !commits.length) return []
  const out = ['', `Code: ${commits.length} commit${commits.length === 1 ? '' : 's'}${branches.length ? ` · branch${branches.length > 1 ? 'es' : ''} ${branches.join(', ')}` : ''}`]
  for (const c of commits.slice(0, limit)) out.push(`  ${c.hash.slice(0, 7)} ${c.subject} · ${c.author} · ${ago(c.at, nowMs)}`)
  if (commits.length > limit) out.push(`  …and ${commits.length - limit} more`)
  return out
}

/** A branch name for an item: its id and a short slug of its title, e.g. s-12-login-form. */
export function branchName(item: Item): string {
  const slug = item.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').split('-').slice(0, 6).join('-').slice(0, 40).replace(/-+$/, '')
  return `${item.id.toLowerCase()}${slug ? `-${slug}` : ''}`
}

/** The first branch already carrying the item's id: reuse it rather than make a second. */
export function existingBranch(item: Item, branches: string[]): string | undefined {
  return [...branches].sort().find(b => branchIds(b).includes(item.id))
}

export type BranchPlan =
  | { action: 'create'; name: string }
  | { action: 'switch'; name: string }
  | { action: 'stay'; name: string }
  | { action: 'ask'; name: string; reason: string }

/** What starting an item on a branch would do, given git's state: nothing is run here. */
export function planBranch(item: Item, state: { current: string; local: string[]; remote: string[]; dirty: number }, anyway = false): BranchPlan {
  const local = existingBranch(item, state.local)
  const remote = local ? undefined : existingBranch(item, state.remote)
  const name = local ?? remote?.replace(/^[^/]+\//, '') ?? branchName(item)
  if (state.current === name) return { action: 'stay', name }
  if (state.dirty && !anyway) {
    return { action: 'ask', name, reason: `${state.dirty} uncommitted change${state.dirty === 1 ? '' : 's'} in the working tree. Commit or stash first, or start anyway to carry them onto ${name}.` }
  }
  return local || remote ? { action: 'switch', name } : { action: 'create', name }
}

export const openQuestions = (d: Draft) => (d.questions ?? []).filter(q => !q.answer)

/**
 * What planning settled, written onto the board with the plan: decisions and
 * answered questions go into the description of the plan's top item (its first
 * epic or milestone, else its first item), so the reasoning isn't lost.
 */
export function withPlanningNotes(items: ItemInput[], draft: Draft): ItemInput[] {
  const decided = (draft.decisions ?? []).map(d => `- ${d.text}`)
  const answered = (draft.questions ?? []).filter(q => q.answer).map(q => `- ${q.text} → ${q.answer}`)
  if (!decided.length && !answered.length) return items
  const top = items.findIndex(i => i.kind === 'epic' || i.kind === 'milestone')
  const at = top >= 0 ? top : 0
  const notes = [
    ...(decided.length ? ['Decisions:', ...decided] : []),
    ...(answered.length ? [...(decided.length ? [''] : []), 'Questions settled while planning:', ...answered] : []),
  ].join('\n')
  return items.map((it, n) => (n === at ? { ...it, description: [it.description, notes].filter(Boolean).join('\n\n') } : it))
}

/** The epic or milestone whose standing approval lets Claude close this work item, if any. Never for epics or milestones themselves. */
export function doneAllowedUnder(board: Board, item: Item): string | undefined {
  if (item.kind === 'epic' || item.kind === 'milestone') return undefined
  const granted = new Set((board.allow ?? []).filter(a => a.what === 'done').map(a => a.scope))
  return ancestorsOf(board, item).find(i => i.id !== item.id && granted.has(i.id))?.id
}

export type DoneGate = { status?: Status; note?: string; under?: string; refuse?: string }

/**
 * What happens when Claude sets an item to done: allowed under a standing
 * approval (marked), allowed because the user just asked, refused for epics
 * and milestones, or turned into review with a note.
 */
export function gateDone(board: Board, item: Item, userAsked: boolean): DoneGate {
  if (item.kind === 'epic' || item.kind === 'milestone') {
    return userAsked ? {} : { refuse: `${item.id}: epics and milestones are closed by the user (when they asked you to, pass approved_by_user).` }
  }
  if (userAsked) return {}
  const under = doneAllowedUnder(board, item)
  if (under) return { under, note: `Closed under the user's standing approval for ${under}.` }
  return { status: 'review', note: `Sent to review instead of done: closing needs the user's approval (/backlog allow ${item.parent ?? '<epic>'} done lets you close work there).` }
}

export type TodoComment = { file: string; line: number; marker: string; text: string; key: string }

/** The comment markers worth importing, only where they start a comment (so prose and strings don't count). */
export const TODO_PATTERN = '(//|#|/\\*|\\*|<!--|--|;)\\s*(TODO|FIXME|HACK|XXX)\\b'

/** Reads `git grep -n` output into TODO comments; the key ignores line numbers, which move as code changes. */
export function parseTodos(output: string): TodoComment[] {
  const out: TodoComment[] = []
  for (const raw of output.split('\n')) {
    const m = raw.match(/^(.+?):(\d+):(.*)$/)
    if (!m) continue
    const [, file = '', line = '0', rest = ''] = m
    const c = rest.match(/(?:\/\/|#|\/\*|\*|<!--|--|;)\s*(TODO|FIXME|HACK|XXX)\b\s*(?:\([^)]*\))?\s*(?::|-(?=\s))?\s*(.*)$/)
    if (!c) continue
    // Drop the comment's own closing (*/ or -->) from the text.
    const text = (c[2] ?? '').replace(/\s*(?:\*\/|-->)\s*$/, '').trim()
    out.push({ file, line: Number(line), marker: c[1]!, text, key: `${file}::${c[1]}::${text.toLowerCase().replace(/\s+/g, ' ')}` })
  }
  return out
}

/** TODO comments not yet on the board or in an open draft, as items to propose. */
export function todoItems(board: Board, todos: TodoComment[]): ItemInput[] {
  const known = new Set([
    ...board.items.map(i => i.source?.key).filter(Boolean),
    ...(board.drafts ?? []).filter(d => d.status === 'open').flatMap(d => d.items.map(i => i.source?.key)).filter(Boolean),
  ])
  const seen = new Set<string>()
  return todos.filter(t => !known.has(t.key) && !seen.has(t.key) && seen.add(t.key)).map(t => ({
    kind: t.marker === 'TODO' ? 'task' : 'bug',
    title: (t.text || `${t.marker} in ${t.file}`).slice(0, 100),
    description: `From \`${t.file}:${t.line}\` (${t.marker} comment)${t.text ? `:\n\n> ${t.text}` : '.'}`,
    labels: ['from-code'],
    source: { file: t.file, line: t.line, key: t.key },
  }))
}

// ---------- export: Markdown and GitHub Issues ----------

const STATUS_WORDS: Record<Status, string> = {
  later: 'later', todo: 'to do', in_progress: 'in progress', review: 'in review', blocked: 'blocked', done: 'done', cancelled: 'cancelled',
}

/** The board as Markdown: milestones, then their epics, then work items, with checkboxes and progress. */
export function toMarkdown(board: Board, { project = board.project.split('/').filter(Boolean).at(-1) ?? 'project', date = '', open = false }: { project?: string; date?: string; open?: boolean } = {}): string {
  const keep = (i: Item) => !open || !isClosed(i.status)
  const work = (i: Item) => i.kind !== 'epic' && i.kind !== 'milestone'
  const row = (i: Item, depth = 0) => {
    const bits = [`**${i.id}** ${i.title}`, STATUS_WORDS[i.status]]
    if (i.priority === 'high' || i.priority === 'critical') bits.push(i.priority)
    if (i.points !== undefined) bits.push(`${i.points}pt`)
    const a = acceptanceProgress(i)
    if (a) bits.push(`${a.met}/${a.total} criteria`)
    return `${'  '.repeat(depth)}- [${i.status === 'done' ? 'x' : ' '}] ${i.status === 'cancelled' ? `~~${bits.join(' · ')}~~` : bits.join(' · ')}`
  }
  const children = (parent: Item, depth: number): string[] => sortItems(board.items.filter(i => i.parent === parent.id && keep(i)))
    .flatMap(i => [row(i, depth), ...children(i, depth + 1)])
  const epicBlock = (e: Item) => {
    const p = progress(board, e)
    return [`### ${e.id} · ${e.title}`, `_${p.done}/${p.total} done${isClosed(e.status) ? ` · ${STATUS_WORDS[e.status]}` : ''}_`, '', ...children(e, 0), '']
  }
  const out: string[] = [`# Roadmap · ${project}`, '']
  const openWork = board.items.filter(i => work(i) && !isClosed(i.status)).length
  const doneWork = board.items.filter(i => work(i) && i.status === 'done').length
  out.push(`_Generated by Backlog${date ? ` on ${date}` : ''}: ${openWork} open, ${doneWork} done._`, '')
  const milestones = sortItems(board.items.filter(i => i.kind === 'milestone' && keep(i)))
  const placed = new Set<string>()
  for (const m of milestones) {
    const p = progress(board, m)
    out.push(`## ${m.id} · ${m.title}`, `_${p.done}/${p.total} done${m.due ? ` · due ${m.due}` : ''}${isClosed(m.status) ? ` · ${STATUS_WORDS[m.status]}` : ''}_`, '')
    for (const e of sortItems(board.items.filter(i => i.kind === 'epic' && i.milestone === m.id && keep(i)))) { out.push(...epicBlock(e)); placed.add(e.id) }
    const loose = sortItems(board.items.filter(i => work(i) && i.milestone === m.id && !i.parent && keep(i)))
    if (loose.length) out.push(...loose.flatMap(i => [row(i), ...children(i, 1)]), '')
    loose.forEach(i => placed.add(i.id))
  }
  const otherEpics = sortItems(board.items.filter(i => i.kind === 'epic' && !placed.has(i.id) && keep(i)))
  const rest = sortItems(board.items.filter(i => work(i) && !i.parent && !placed.has(i.id) && !(i.milestone && milestones.some(m => m.id === i.milestone)) && keep(i)))
  if (otherEpics.length || rest.length) {
    out.push('## Not in a milestone', '')
    for (const e of otherEpics) out.push(...epicBlock(e))
    if (rest.length) out.push(...rest.flatMap(i => [row(i), ...children(i, 1)]), '')
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n'
}

/** An item as a GitHub issue body: why, criteria as a checklist, and where it is tracked. */
export function issueBody(board: Board, i: Item): string {
  const parent = i.parent ? resolveId(board, i.parent) : undefined
  const milestone = i.milestone ? resolveId(board, i.milestone) : undefined
  return [
    i.description?.trim() || '',
    i.acceptance?.length ? `### Acceptance criteria\n${i.acceptance.map((c, n) => `- [${i.met?.[n] ? 'x' : ' '}] ${c}`).join('\n')}` : '',
    [parent && `Part of ${parent.id} ${parent.title}.`, milestone && `Milestone: ${milestone.id} ${milestone.title}.`].filter(Boolean).join(' '),
    `<sub>Tracked in Backlog as **${i.id}** (${i.kind}, ${STATUS_WORDS[i.status]}${i.points !== undefined ? `, ${i.points}pt` : ''}).</sub>`,
  ].filter(Boolean).join('\n\n')
}

export const issueTitle = (i: Item) => `${i.id}: ${i.title}`

export type GithubPlan = { create: Item[]; edit: Item[]; close: Item[]; reopen: Item[] }

/**
 * What mirroring the board to GitHub Issues would do: open work items without
 * an issue get one (later items wait), changed titles or bodies are edited,
 * and issues follow their items closed and reopened.
 */
export function planGithub(board: Board): GithubPlan {
  const work = board.items.filter(i => i.kind !== 'epic' && i.kind !== 'milestone')
  const hash = (i: Item) => fingerprint(`${issueTitle(i)}\n${issueBody(board, i)}`)
  return {
    create: sortItems(work.filter(i => !i.github && !isClosed(i.status) && i.status !== 'later')),
    edit: work.filter(i => i.github && i.github.hash !== hash(i)),
    close: work.filter(i => i.github?.state === 'open' && isClosed(i.status)),
    reopen: work.filter(i => i.github?.state === 'closed' && !isClosed(i.status)),
  }
}

export const issueHash = (board: Board, i: Item) => fingerprint(`${issueTitle(i)}\n${issueBody(board, i)}`)

/**
 * Re-stamps history entries for a commit as Claude's, in this session: for when
 * a background scan linked Claude's own commit before it was known to be Claude's.
 */
export function claimCommit(board: Board, hash: string, session: string): Board {
  const short = hash.slice(0, 7)
  let changed = false
  const items = board.items.map(i => {
    if (!i.code?.commits.some(c => c.hash.startsWith(short) || hash.startsWith(c.hash))) return i
    const activity = (i.activity ?? []).map(a => {
      if (a.author !== 'user' || !a.text.startsWith(`commit ${short}`)) return a
      changed = true
      return { ...a, author: 'claude' as const, session }
    })
    return { ...i, activity }
  })
  return changed ? { ...board, items } : board
}

