files.types/index.d.ts:
export type Kind = 'milestone' | 'epic' | 'story' | 'task' | 'bug'
export type Status = 'later' | 'todo' | 'in_progress' | 'review' | 'blocked' | 'done' | 'cancelled'
export type Priority = 'low' | 'medium' | 'high' | 'critical'
export type View = 'active' | 'later' | 'epics' | 'milestones' | 'done' | 'all'

/** A comment in the code an item was imported from; key ignores the line number, which moves as code changes. */
export type SourceRef = { file: string; line: number; key: string }

export type CommitRef = { hash: string; subject: string; author: string; at: string; branch?: string }
export type CodeRecord = { branches: string[]; commits: CommitRef[] }

export type Comment = {
  at: string
  author: 'claude' | 'user'
  text: string
  /** The Claude Code session that made the change, so each session can tell its own work from others'. */
  session?: string
}

export type Item = {
  id: string
  kind: Kind
  title: string
  description?: string
  status: Status
  priority: Priority
  /** An epic (or a story, for subtasks) this item belongs to. */
  parent?: string
  /** The milestone this item targets. */
  milestone?: string
  labels: string[]
  points?: number
  acceptance?: string[]
  /** Which acceptance criteria are met, by position. */
  met?: boolean[]
  /** Manual position within its status; ranked items come before unranked ones. */
  rank?: number
  /** The code that went into the item, read from git. */
  code?: CodeRecord
  /** Set when Claude closed the item under a standing approval: the epic or milestone that allowed it. */
  closedUnder?: string
  /** Where an imported item came from in the code (a TODO comment), so it's never imported twice. */
  source?: SourceRef
  /** The GitHub issue mirroring this item, once exported; hash is of the title and body last sent. */
  github?: { number: number; url: string; state: 'open' | 'closed'; hash: string }
  /** YYYY-MM-DD */
  due?: string
  comments: Comment[]
  /** What changed and who changed it, newest last, capped. */
  activity?: Comment[]
  createdAt: string
  updatedAt: string
  closedAt?: string
}

/** An item Claude proposes, before it is on the board: `ref` links items within the proposal. */
export type ProposedItem = {
  ref?: string
  kind: string
  title: string
  description?: string
  status?: string
  priority?: string
  parent?: string
  milestone?: string
  labels?: string[]
  points?: number
  acceptance?: string[]
  due?: string
  source?: SourceRef
}

/** A plan waiting for the user: the items, and which of them they keep. (Session-only; superseded by Draft.) */
export type Proposal = { at: string; items: ProposedItem[]; include: boolean[] }

/** A plan Claude and the user shape together until it is accepted onto the board, or discarded. */
export type Draft = {
  id: string
  topic: string
  status: 'open' | 'accepted' | 'discarded'
  items: ProposedItem[]
  include: boolean[]
  createdAt: string
  updatedAt: string
  /** Ids the accepted items got on the board. */
  created?: string[]
  /** Who changed what in the draft, so each side sees the other's edits. Capped. */
  log?: Comment[]
  /** Fields the user changed per item ref since Claude last revised them: Claude must not overwrite these silently. */
  userEdited?: Record<string, string[]>
  /** The next generated item ref (i<n>): refs are never reused within a draft. */
  nextRef?: number
  /** What still has to be worked out, and what was settled; both carry over onto the board on accept. */
  questions?: DraftQuestion[]
  decisions?: DraftDecision[]
  nextQuestion?: number
}

export type DraftQuestion = { id: string; text: string; at: string; answer?: string; answeredAt?: string }
export type DraftDecision = { text: string; at: string; author: 'claude' | 'user' }

/** One undoable change: the board before it, and a fingerprint of the board it produced. */
export type Change = { at: string; label: string; before: Board; after: string }

export type Board = {
  version: 1
  project: string
  nextNumber: number
  items: Item[]
  /** Board-level events that leave no item history behind: deletions and undos. Capped. */
  log?: Comment[]
  /** Standing approvals the user gave: plans Claude proposes inside these epics or milestones are created without asking. */
  allow?: Allowance[]
  /** Plans being shaped; closed ones are kept briefly for reference. */
  drafts?: Draft[]
  nextDraft?: number
}

/** plans: Claude's plans there skip review. done: Claude may close its own verified work there. */
export type Allowance = { scope: string; what: 'plans' | 'done'; at: string }

declare module 'claude-code' {
  interface PluginState {
    'backlog': {
      board: Board | null
      view: View
      selected: string | null
      editing: boolean
      lastChange: string | null
      confirmDelete: string | null
      query: string
      expanded: string | null
      seenAt: string
      bandHidden: boolean
      proposal: Proposal | null
      activeDraft: string | null
      planConfirm: string | null
      planEdit: string | null
      focused: string | null
      path: string
    }
  }
}
